INSERT INTO `courses` (`id`, `slug`, `title`, `description`, `level`, `thumbnail_url`, `published`, `sort_order`, `estimated_minutes`, `created_at`, `updated_at`) VALUES (1,'hsk-1-co-ban','Tiếng Trung cơ bản HSK 1','Khóa học nhập môn dành cho người mới bắt đầu, không cần biết trước một chữ Hán nào. Bạn sẽ học bảng phiên âm pinyin, bốn thanh điệu, 150 từ vựng HSK 1 và các mẫu câu giao tiếp thiết yếu: chào hỏi, giới thiệu bản thân, gia đình, số đếm, thời gian, mua sắm, đồ ăn và thời tiết. Sau 12 bài học bạn có thể tự tin làm bài thi HSK 1 và giao tiếp trong những tình huống đơn giản hằng ngày.','HSK1','https://cdn.hoctiengtrung.vn/courses/hsk1-co-ban.jpg',_binary '',1,720,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(2,'hsk-2-so-cap','Tiếng Trung sơ cấp HSK 2','Tiếp nối HSK 1, khóa học mở rộng vốn từ lên 300 từ và bổ sung các cấu trúc ngữ pháp quan trọng như so sánh với 比, bổ ngữ trạng thái với 得, trợ từ 了 và 过. Nội dung xoay quanh những tình huống thực tế: hỏi đường, gọi món trong nhà hàng, đi khám bệnh, đặt phòng khách sạn, gọi điện hẹn gặp và miêu tả người. Kết thúc khóa học bạn đủ khả năng vượt qua kỳ thi HSK 2 và duy trì hội thoại ngắn bằng tiếng Trung.','HSK2','https://cdn.hoctiengtrung.vn/courses/hsk2-so-cap.jpg',_binary '',2,840,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(3,'hsk-3-trung-cap','Tiếng Trung trung cấp HSK 3','Khóa học đưa bạn từ trình độ giao tiếp cơ bản lên mức có thể kể chuyện, trình bày ý kiến và xử lý hầu hết tình huống khi sinh sống, học tập tại Trung Quốc. Trọng tâm là 600 từ vựng HSK 3, hệ thống bổ ngữ kết quả và bổ ngữ xu hướng, câu chữ 把, câu bị động và các liên từ phức hợp. Mỗi bài đều có phần luyện nghe, luyện đọc và bài tập viết chữ Hán.','HSK3','https://cdn.hoctiengtrung.vn/courses/hsk3-trung-cap.jpg',_binary '',3,960,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(4,'hsk-4-nang-cao','Tiếng Trung nâng cao HSK 4','Lộ trình nâng cao với 1200 từ vựng HSK 4, giúp bạn thảo luận về công việc, xã hội, môi trường và bày tỏ quan điểm cá nhân một cách mạch lạc. Khóa học tập trung vào cụm từ cố định, cách dùng thành ngữ thông dụng, kỹ năng đọc hiểu văn bản dài và viết đoạn văn 80 chữ theo yêu cầu đề thi. Nội dung đang được biên soạn và sẽ mở trong thời gian tới.','HSK4','https://cdn.hoctiengtrung.vn/courses/hsk4-nang-cao.jpg',_binary '\0',4,1080,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(5,'hsk-5-cao-cap','Tiếng Trung cao cấp HSK 5','Khóa học dành cho người học đã vững HSK 4, hướng tới 2500 từ vựng và khả năng đọc báo, xem phim, nghe tin tức tiếng Trung mà không cần phụ đề. Chương trình đi sâu vào thành ngữ bốn chữ, văn phong viết, tiếng Trung thương mại và kỹ năng thuyết trình, tranh luận. Đây là bản đề cương, các bài học chi tiết sẽ được cập nhật sau.','HSK5','https://cdn.hoctiengtrung.vn/courses/hsk5-cao-cap.jpg',_binary '\0',5,1200,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(6,'hsk-6-thanh-thao','Tiếng Trung thành thạo HSK 6','Cấp độ cao nhất của hệ thống HSK với hơn 5000 từ vựng, hướng tới năng lực sử dụng tiếng Trung gần như người bản ngữ trong môi trường học thuật và chuyên môn. Khóa học rèn văn viết trang trọng, điển cố và Hán ngữ cổ còn dùng trong văn viết hiện đại, phân tích văn bản học thuật và chiến lược luyện thi HSK 6. Đề cương tham khảo, nội dung chi tiết đang xây dựng.','HSK6','https://cdn.hoctiengtrung.vn/courses/hsk6-thanh-thao.jpg',_binary '\0',6,1440,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000');
