INSERT INTO `decks` (`id`, `owner_id`, `topic_id`, `slug`, `name`, `description`, `hsk_level`, `is_public`, `is_system`, `card_count`, `created_at`, `updated_at`) VALUES (1,NULL,NULL,'hsk1-tron-bo','HSK 1 - Trọn bộ','Trọn bộ từ vựng HSK cấp 1. Học và ôn tập theo thuật toán lặp lại ngắt quãng SM-2, phù hợp cho người mới bắt đầu học tiếng Trung.',1,_binary '',_binary '',150,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(2,NULL,NULL,'hsk2-tron-bo','HSK 2 - Trọn bộ','Trọn bộ từ vựng HSK cấp 2. Mở rộng vốn từ sau khi đã nắm vững HSK 1, chuẩn bị cho kỳ thi HSK cấp 2.',2,_binary '',_binary '',150,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(3,NULL,1,'chu-de-chao-hoi','Chủ đề: Chào hỏi','Từ vựng chào hỏi, làm quen và giao tiếp cơ bản hằng ngày bằng tiếng Trung.',NULL,_binary '',_binary '',20,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(4,NULL,2,'chu-de-gia-dinh','Chủ đề: Gia đình','Từ vựng về các thành viên trong gia đình và quan hệ họ hàng.',NULL,_binary '',_binary '',19,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(5,NULL,3,'chu-de-so-dem','Chủ đề: Số đếm','Từ vựng về số đếm, số lượng và cách dùng lượng từ trong tiếng Trung.',NULL,_binary '',_binary '',20,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(6,NULL,4,'chu-de-thoi-gian','Chủ đề: Thời gian','Từ vựng về ngày tháng, giờ giấc, thứ trong tuần và các mốc thời gian.',NULL,_binary '',_binary '',20,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(7,NULL,5,'chu-de-mau-sac','Chủ đề: Màu sắc','Từ vựng về màu sắc và cách miêu tả màu sắc của sự vật.',NULL,_binary '',_binary '',4,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(8,NULL,6,'chu-de-do-an-thuc-uong','Chủ đề: Đồ ăn và thức uống','Từ vựng về món ăn, đồ uống và các hoạt động ăn uống thường ngày.',NULL,_binary '',_binary '',19,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(9,NULL,7,'chu-de-hoc-tap','Chủ đề: Học tập','Từ vựng về trường lớp, sách vở, thầy cô và việc học tiếng Trung.',NULL,_binary '',_binary '',20,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(10,NULL,8,'chu-de-cong-viec','Chủ đề: Công việc','Từ vựng về nghề nghiệp, nơi làm việc và các hoạt động trong công việc.',NULL,_binary '',_binary '',10,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000');
