/*!40000 ALTER TABLE `lesson_grammar` DISABLE KEYS */;
INSERT INTO `lesson_grammar` (`id`, `lesson_id`, `title`, `structure`, `explanation`, `example_zh`, `example_vi`, `sort_order`) VALUES (1,1,'Câu vị ngữ động từ với 是','Chủ ngữ + 是 + Danh từ','Động từ 是 nối chủ ngữ với danh từ để khẳng định danh tính, nghề nghiệp hoặc quốc tịch. Dạng phủ định là 不是. Lưu ý 是 không dùng trước tính từ, đây là lỗi phổ biến nhất của người Việt mới học.','我是越南人，他是老师。','Tôi là người Việt Nam, anh ấy là giáo viên.',1),(2,1,'Câu hỏi với trợ từ 吗','Câu trần thuật + 吗？','Chỉ cần thêm 吗 vào cuối một câu trần thuật là thành câu hỏi có hoặc không, trật tự từ giữ nguyên hoàn toàn. Đây là kiểu câu hỏi đơn giản nhất trong tiếng Trung.','你好吗？你是学生吗？','Bạn khỏe không? Bạn là học sinh phải không?',2),(3,1,'Hỏi và nói tên với 叫','Chủ ngữ + 叫 + tên','Động từ 叫 dùng để nói tên gọi. Hỏi tên đầy đủ dùng 你叫什么名字, hỏi họ một cách trang trọng dùng 您贵姓 và trả lời bằng 我姓…','你叫什么名字？我叫阮明。','Bạn tên là gì? Tôi tên là Nguyễn Minh.',3),(4,2,'Hỏi số lượng nhỏ với 几','几 + lượng từ + danh từ','Từ để hỏi 几 dùng khi người hỏi dự đoán câu trả lời nhỏ hơn 10, luôn phải đi kèm lượng từ. Hỏi ngày, thứ, giờ đều dùng 几.','今天几号？你有几个哥哥？','Hôm nay ngày mấy? Bạn có mấy anh trai?',1),(5,2,'Hỏi số lượng lớn với 多少','多少 + (lượng từ) + danh từ','Khác với 几, từ 多少 dùng cho số lượng không giới hạn và có thể đứng trực tiếp trước danh từ mà không cần lượng từ. Hỏi giá tiền và số điện thoại đều dùng 多少.','你的电话号码是多少？这个多少钱？','Số điện thoại của bạn là bao nhiêu? Cái này bao nhiêu tiền?',2),(6,2,'Cách nói ngày tháng và thứ','年 + 月 + 号 / 星期 + số','Trật tự thời gian đi từ đơn vị lớn tới đơn vị nhỏ. Thứ trong tuần ghép 星期 với số từ 一 đến 六, riêng Chủ nhật là 星期天 hoặc 星期日. Câu chỉ ngày tháng có thể lược bỏ động từ 是.','今天二零二六年一月一号，星期四。','Hôm nay ngày 1 tháng 1 năm 2026, thứ Năm.',3),(7,3,'Câu tồn tại và sở hữu với 有','Chủ ngữ + 有 + số lượng + lượng từ + danh từ','Động từ 有 diễn tả sở hữu hoặc tồn tại. Dạng phủ định bắt buộc dùng 没有, tuyệt đối không nói 不有.','我家有四口人，我没有妹妹。','Nhà tôi có bốn người, tôi không có em gái.',1),(8,3,'Trợ từ kết cấu 的 chỉ sở hữu','Người sở hữu + 的 + vật sở hữu','Trợ từ 的 đứng giữa hai danh từ để chỉ quan hệ sở hữu. Khi nói về người thân hoặc tổ chức gắn bó, 的 thường được lược bỏ: 我妈妈, 我家, 我们学校.','这是我的书，那是姐姐的手机。','Đây là sách của tôi, kia là điện thoại của chị gái.',2),(9,3,'Lượng từ 口 và 个 khi đếm người','Số từ + 口/个 + 人','Lượng từ 口 chuyên dùng để đếm nhân khẩu trong một gia đình, còn 个 dùng để đếm người nói chung trong các ngữ cảnh khác.','我家有五口人，我们班有二十个人。','Nhà tôi có năm người, lớp tôi có hai mươi người.',3),(10,4,'Cách nói giờ với 点 và 分','Số + 点 + số + 分','Giờ dùng 点, phút dùng 分, rưỡi dùng 半, kém dùng 差. Hỏi giờ dùng 几点. Buổi trong ngày như 上午, 中午, 下午, 晚上 đặt trước số giờ.','现在下午三点十五分，我们四点半见。','Bây giờ 3 giờ 15 chiều, 4 rưỡi chúng ta gặp nhau.',1),(11,4,'Vị trí của trạng ngữ thời gian','Chủ ngữ + thời gian + động từ + tân ngữ','Trạng ngữ thời gian bắt buộc đứng trước động từ, khác hẳn tiếng Việt vốn hay đặt ở cuối câu. Có thể chuyển thời gian lên đầu câu để nhấn mạnh.','我每天七点起床，晚上十一点睡觉。','Ngày nào tôi cũng dậy lúc 7 giờ, 11 giờ đêm mới đi ngủ.',2),(12,4,'Hỏi thời điểm với 什么时候','Chủ ngữ + 什么时候 + Động từ','Cụm 什么时候 hỏi về thời điểm chung chung, đứng ở vị trí của trạng ngữ thời gian trong câu trả lời, tức là trước động từ.','你什么时候去中国？我下个月去。','Khi nào bạn đi Trung Quốc? Tháng sau tôi đi.',3),(13,5,'Động từ năng nguyện 想','Chủ ngữ + 想 + động từ + tân ngữ','Động từ 想 đứng trước động từ chính để nói mong muốn làm việc gì, phủ định là 不想. Khi 想 đứng trước danh từ chỉ người thì mang nghĩa nhớ nhung.','我想喝咖啡，不想吃饭。','Tôi muốn uống cà phê, không muốn ăn cơm.',1),(14,5,'Động từ 喜欢 với tân ngữ kép','喜欢 + danh từ / động từ + tân ngữ','Sau 喜欢 có thể là danh từ hoặc cả một cụm động từ. Muốn nhấn mạnh mức độ thì thêm 很 hoặc 非常 phía trước.','我很喜欢吃中国菜，也喜欢中国茶。','Tôi rất thích ăn món Trung Quốc, cũng thích trà Trung Quốc.',2),(15,5,'Phủ định với 不','不 + động từ / tính từ','Phó từ 不 phủ định thói quen, ý muốn hoặc trạng thái hiện tại và tương lai. Riêng với động từ 有 phải dùng 没有. Thanh điệu của 不 biến thành thanh 2 khi đứng trước âm tiết thanh 4.','我不吃肉，也不喝酒。','Tôi không ăn thịt, cũng không uống rượu.',3),(16,6,'Hỏi giá với 多少钱','Vật + 多少钱？','Đây là mẫu câu hỏi giá cố định. Đơn vị tiền khẩu ngữ là 块, 毛, 分, còn văn viết dùng 元, 角, 分.','这件衣服多少钱？三十五块。','Chiếc áo này bao nhiêu tiền? Ba mươi lăm tệ.',1),(17,6,'Lượng từ thường gặp 个, 本, 件','Số từ + lượng từ + danh từ','Giữa số từ và danh từ bắt buộc có lượng từ. 个 dùng chung cho người và vật, 本 dùng cho sách vở, 件 dùng cho quần áo và sự việc, 张 dùng cho vật phẳng.','我买两本书和一件衣服。','Tôi mua hai quyển sách và một chiếc áo.',2),(18,6,'Cấu trúc cảm thán 太…了','太 + tính từ + 了','Cấu trúc 太…了 diễn tả mức độ vượt quá, mang sắc thái cảm thán, thường dùng khi khen hoặc chê. Dạng phủ định 不太 lại chỉ mức độ nhẹ đi.','太贵了！这儿的东西不太便宜。','Đắt quá! Đồ ở đây không rẻ lắm.',3),(19,7,'Động từ 在 chỉ vị trí','Vật + 在 + nơi chốn','Động từ 在 nói vật hoặc người ở đâu. Hỏi vị trí dùng 在哪儿. Phủ định là 不在.','书在桌子上，老师不在办公室。','Sách ở trên bàn, cô giáo không có ở văn phòng.',1),(20,7,'Từ chỉ phương vị đặt sau danh từ','Danh từ + 上/里/下/前/后','Từ chỉ phương vị trong tiếng Trung đứng SAU danh từ nơi chốn, ngược với tiếng Việt. 桌子上 nghĩa là trên bàn, 房间里 nghĩa là trong phòng.','房间里有一台电脑，桌子下有一个包。','Trong phòng có một máy tính, dưới bàn có một cái túi.',2),(21,7,'Đại từ chỉ định 这 và 那','这/那 + lượng từ + danh từ','Đại từ 这 chỉ vật ở gần, 那 chỉ vật ở xa. Khi đi với danh từ đếm được phải chèn lượng từ ở giữa: 这本书, 那个人.','这本书是我的，那个杯子是他的。','Quyển sách này là của tôi, cái cốc kia là của cậu ấy.',3),(22,8,'Động từ năng nguyện 会','Chủ ngữ + 会 + động từ','Động từ 会 chỉ kỹ năng có được nhờ học tập, phủ định là 不会. Muốn nói mức độ ít thì thêm 一点儿 sau tân ngữ.','我会说汉语，但是不会写汉字。','Tôi biết nói tiếng Trung nhưng không biết viết chữ Hán.',1),(23,8,'Giới từ 在 chỉ nơi chốn của hành động','Chủ ngữ + 在 + nơi chốn + động từ','Khi 在 làm giới từ, cụm giới từ phải đứng TRƯỚC động từ chính. Không được nói 我学习在学校 theo trật tự tiếng Việt.','我在大学学习汉语。','Tôi học tiếng Trung ở trường đại học.',2),(24,8,'Liên từ 和 nối danh từ','Danh từ + 和 + danh từ','Liên từ 和 chỉ nối danh từ hoặc đại từ, không dùng để nối hai mệnh đề như chữ và trong tiếng Việt. Muốn nối hai câu thì dùng dấu phẩy hoặc phó từ 也.','我和我的同学都喜欢汉语。','Tôi và bạn học của tôi đều thích tiếng Trung.',3),(25,9,'Câu vị ngữ tính từ với 很','Chủ ngữ + 很 + tính từ','Câu vị ngữ tính từ không dùng động từ 是. Phó từ 很 giữ vai trò liên kết, thường không mang nghĩa rất khi không nhấn trọng âm.','今天很热，昨天很冷。','Hôm nay rất nóng, hôm qua rất lạnh.',1),(26,9,'Phủ định câu vị ngữ tính từ','Chủ ngữ + 不 + tính từ','Khi phủ định câu vị ngữ tính từ, bỏ 很 và thay bằng 不. Muốn giảm nhẹ thì dùng 不太.','今天不冷，天气不太好。','Hôm nay không lạnh, thời tiết không được đẹp lắm.',2),(27,9,'Hỏi tình trạng với 怎么样','Chủ đề + 怎么样？','Cụm 怎么样 hỏi về tình trạng, chất lượng hoặc ý kiến, tương đương thế nào trong tiếng Việt. Cũng dùng để đề nghị: 我们去看电影，怎么样？','今天天气怎么样？这个菜怎么样？','Thời tiết hôm nay thế nào? Món này thế nào?',3),(28,10,'Câu liên động chỉ phương tiện','Chủ ngữ + 坐/骑 + phương tiện + 去 + nơi chốn','Hai động từ nối nhau theo đúng trình tự xảy ra: trước hết lên phương tiện, sau đó tới nơi. Xe đạp và xe máy dùng 骑, các phương tiện có chỗ ngồi dùng 坐.','我坐公共汽车去学校，他骑自行车去。','Tôi đi xe buýt tới trường, cậu ấy đi xe đạp.',1),(29,10,'Động từ 去 và 来','去/来 + nơi chốn','Động từ 去 chỉ hướng đi xa khỏi người nói, 来 chỉ hướng tới gần người nói. Sau hai động từ này, danh từ nơi chốn đứng trực tiếp, không cần giới từ.','你去哪儿？我来北京学习汉语。','Bạn đi đâu? Tôi đến Bắc Kinh học tiếng Trung.',2),(30,10,'Hỏi cách thức với 怎么','怎么 + động từ','Từ để hỏi 怎么 hỏi về phương thức tiến hành hành động, đứng ngay trước động từ. Cần phân biệt với 怎么样 hỏi tình trạng.','这个字怎么读？你怎么去机场？','Chữ này đọc thế nào? Bạn tới sân bay bằng cách nào?',3),(31,11,'Trợ từ 了 chỉ sự thay đổi trạng thái','Câu + 了','Chữ 了 đứng cuối câu báo hiệu tình hình đã thay đổi so với trước đó. 我生病了 nghĩa là trước khỏe, giờ đã ốm.','我生病了，不能去上课了。','Tôi bị ốm rồi, không đi học được nữa.',1),(32,11,'Phân biệt phủ định 不 và 没','不 + động từ (hiện tại, tương lai) / 没 + động từ (quá khứ)','Phó từ 不 phủ định ý muốn, thói quen, tình trạng hiện tại và tương lai. Phó từ 没 phủ định việc đã không xảy ra hoặc chưa xảy ra trong quá khứ.','我昨天没去医院，今天也不想去。','Hôm qua tôi đã không đi bệnh viện, hôm nay cũng không muốn đi.',2),(33,11,'Câu cầu khiến lịch sự với 请','请 + động từ + tân ngữ','Chữ 请 đặt đầu câu làm lời đề nghị trở nên lịch sự, tương đương xin mời hoặc làm ơn trong tiếng Việt.','请坐，请喝茶，请再说一遍。','Mời ngồi, mời uống trà, xin nói lại một lần nữa.',3),(34,12,'Trật tự thành phần câu tiếng Trung','Chủ ngữ + thời gian + nơi chốn + phương thức + động từ + tân ngữ','Đây là bộ khung trật tự cố định của câu tiếng Trung. Nhớ đúng thứ tự này giúp tránh phần lớn lỗi sai khi dịch từ tiếng Việt sang.','我明天在家跟朋友一起看电视。','Ngày mai tôi xem tivi cùng bạn ở nhà.',1),(35,12,'Câu hỏi chính phản','Động từ + 不 + động từ','Ghép dạng khẳng định và phủ định của cùng một động từ hoặc tính từ để tạo câu hỏi, sắc thái tương đương câu hỏi với 吗 nhưng không được dùng chung với 吗.','你去不去？这个菜好吃不好吃？','Bạn có đi không? Món này có ngon không?',2),(36,12,'Câu hỏi lược với 呢','Danh từ / đại từ + 呢？','Trợ từ 呢 tạo câu hỏi rút gọn dựa trên nội dung vừa nói, tránh lặp lại cả câu. Ngoài ra 呢 còn hỏi vị trí: 我的书呢？','我很好，你呢？我的手机呢？','Tôi khỏe, còn bạn? Điện thoại của tôi đâu rồi?',3),(37,13,'Cấu trúc 从…到… chỉ điểm đầu và điểm cuối','从 + A + 到 + B','Cặp giới từ 从…到… dùng cho cả khoảng không gian lẫn khoảng thời gian. Cụm này đứng trước động từ chính của câu.','从我家到公司要三十分钟。','Từ nhà tôi tới công ty mất ba mươi phút.',1),(38,13,'Giới từ 往 chỉ hướng di chuyển','往 + phương hướng + động từ','Giới từ 往 nêu hướng của hành động và luôn đứng trước động từ. Các từ hướng thường gặp: 前, 后, 左, 右, 东, 西.','一直往前走，到路口往右拐。','Cứ đi thẳng, tới ngã tư thì rẽ phải.',2),(39,13,'Giới từ 离 chỉ khoảng cách','A + 离 + B + 远/近','Giới từ 离 nói khoảng cách giữa hai điểm, thường đi với 远, 近 hoặc một con số cụ thể. Đừng nhầm 离 với 从.','我家离学校很近，只有一公里。','Nhà tôi rất gần trường, chỉ một cây số.',3),(40,14,'Động từ 要 khi gọi món','Chủ ngữ + 要 + số lượng + lượng từ + món ăn','Động từ 要 mang nghĩa muốn lấy, dùng phổ biến khi gọi món và mua hàng. Sắc thái dứt khoát hơn 想. Phủ định lịch sự là 不用了.','我要一碗牛肉面和一杯茶。','Cho tôi một bát mì bò và một cốc trà.',1),(41,14,'Câu hỏi lựa chọn với 还是','A + 还是 + B？','Liên từ 还是 dùng trong câu hỏi để đưa ra hai lựa chọn. Trong câu trần thuật phải dùng 或者 chứ không dùng 还是.','你喝茶还是喝咖啡？','Bạn uống trà hay uống cà phê?',2),(42,14,'Phân biệt 有点儿 và 一点儿','有点儿 + tính từ / tính từ + 一点儿','Cụm 有点儿 đứng trước tính từ và mang sắc thái không hài lòng. Cụm 一点儿 đứng sau tính từ, chỉ mức độ chênh lệch nhỏ và thường dùng khi đề nghị.','这个菜有点儿咸，请淡一点儿。','Món này hơi mặn, làm ơn nhạt hơn một chút.',3),(43,15,'Phó từ tần suất 常常 và 有时候','Chủ ngữ + 常常/有时候 + động từ','Phó từ chỉ tần suất đứng trước động từ. 常常 nhấn mạnh việc lặp lại thường xuyên, 有时候 chỉ đôi lúc, 从来不 nghĩa là chưa bao giờ.','我常常去游泳，有时候去爬山。','Tôi thường đi bơi, thỉnh thoảng đi leo núi.',1),(44,15,'Động từ 觉得 nêu cảm nhận','Chủ ngữ + 觉得 + mệnh đề','Động từ 觉得 dẫn ra nhận xét chủ quan, theo sau là cả một mệnh đề chứ không phải một danh từ đơn lẻ.','我觉得学汉语很有意思。','Tôi thấy học tiếng Trung rất thú vị.',2),(45,15,'Giới từ 跟 chỉ đối tượng cùng làm','Chủ ngữ + 跟 + người + động từ','Giới từ 跟 nêu người cùng thực hiện hành động, đứng trước động từ, thường đi kèm phó từ 一起.','周末我跟朋友一起去看电影。','Cuối tuần tôi đi xem phim cùng bạn.',3),(46,16,'Giới từ 在 chỉ nơi làm việc','Chủ ngữ + 在 + nơi chốn + động từ','Cụm giới từ chỉ nơi chốn bắt buộc đứng trước động từ. Đây là lỗi sai kinh điển vì tiếng Việt đặt nơi chốn ở cuối câu.','我在一家中国公司工作。','Tôi làm việc ở một công ty Trung Quốc.',1),(47,16,'Cặp liên từ 因为…所以…','因为 + nguyên nhân, 所以 + kết quả','Tiếng Trung thường dùng đủ cả hai vế của cặp liên từ, khác tiếng Việt hay lược bớt một vế. Có thể đảo vế kết quả lên trước.','因为今天有会议，所以我不能去。','Vì hôm nay có cuộc họp nên tôi không đi được.',2),(48,16,'Phó từ 已经 kết hợp với 了','已经 + động từ + 了','Phó từ 已经 chỉ việc đã hoàn tất và hầu như luôn đi cùng trợ từ 了 ở cuối câu. Phủ định dùng 还没有…呢.','我已经工作三年了，还没有换工作呢。','Tôi đã đi làm ba năm rồi, vẫn chưa đổi việc.',3),(49,17,'Câu so sánh với 比','A + 比 + B + tính từ','Công thức so sánh hơn cơ bản nhất. Sau tính từ không được thêm 很 hay 太, nhưng có thể thêm 一点儿, 多了 hoặc con số cụ thể để nêu mức chênh lệch.','这件衣服比那件贵一点儿。','Chiếc áo này đắt hơn chiếc kia một chút.',1),(50,17,'Động từ năng nguyện 可以 xin phép','可以 + động từ + 吗？','Động từ 可以 dùng để xin phép hoặc hỏi khả năng được phép. Trả lời đồng ý là 可以, từ chối thường dùng 不行 chứ ít khi nói 不可以 trực diện.','我可以试试这件衣服吗？','Tôi mặc thử chiếc áo này được không?',2),(51,17,'Kết cấu chữ 的 thay thế danh từ','Tính từ / màu sắc + 的','Khi ngữ cảnh đã rõ, có thể lược danh từ phía sau 的 và dùng cụm 的 làm chủ ngữ hoặc tân ngữ, tương đương cái màu đỏ, cái rẻ trong tiếng Việt.','我要红色的，不要白色的。','Tôi lấy cái màu đỏ, không lấy cái màu trắng.',3),(52,18,'Động từ năng nguyện 要 chỉ sự cần thiết','Chủ ngữ + 要 + động từ','Ở đây 要 mang nghĩa cần phải, nên. Điều đặc biệt là phủ định của nó không phải 不要 mà là 不用, vì 不要 nghĩa là đừng.','你要多休息，不用吃药。','Bạn cần nghỉ ngơi nhiều, không cần uống thuốc.',1),(53,18,'Câu cầu khiến phủ định với 别','别 + động từ + tân ngữ','Phó từ 别 đặt đầu vị ngữ để khuyên đừng làm gì. Thêm 请 phía trước cho lịch sự, thêm 了 cuối câu để yêu cầu dừng việc đang làm.','别吃太冷的东西，别熬夜了。','Đừng ăn đồ quá lạnh, đừng thức khuya nữa.',2),(54,18,'Cách nói tần suất dùng thuốc với 次','Thời gian + động từ + số + 次','Lượng từ động tác 次 đếm số lần thực hiện hành động, đứng sau động từ. Đây là bổ ngữ số lượng động tác rất hay gặp khi nói về liều thuốc.','这个药一天吃三次，一次两片。','Thuốc này ngày uống ba lần, mỗi lần hai viên.',3),(55,19,'Động từ 打算 nêu dự định','Chủ ngữ + 打算 + động từ','Động từ 打算 diễn tả kế hoạch đã cân nhắc, mức độ chắc chắn cao hơn 想. Phủ định là 不打算.','我打算下个月去北京旅游。','Tôi định tháng sau đi du lịch Bắc Kinh.',1),(56,19,'Giới từ 帮 nhờ vả','帮 + người + động từ','Giới từ 帮 nêu người được giúp, đứng trước động từ. Thêm 请 ở đầu và 一下 ở cuối câu khiến lời nhờ vả nhẹ nhàng hơn nhiều.','请帮我叫一辆出租车。','Làm ơn gọi giúp tôi một chiếc taxi.',2),(57,19,'Hình thức lặp động từ','Động từ + động từ hoặc động từ + 一下','Lặp lại động từ hoặc thêm 一下 làm giảm mức độ trang trọng, mang nghĩa làm thử một chút, khiến câu nói thân thiện và lịch sự hơn.','你等一下，我看看这个房间。','Bạn đợi một chút, để tôi xem qua căn phòng này.',3),(58,20,'Cấu trúc 正在…呢 chỉ hành động đang diễn ra','正在 + động từ + 呢','Cấu trúc này nói hành động đang tiếp diễn tại thời điểm nói. Có thể lược bớt thành 在…呢 hoặc chỉ dùng 呢 ở cuối câu.','他正在开会呢，等一下再打吧。','Anh ấy đang họp, lát nữa gọi lại nhé.',1),(59,20,'Giới từ 给 chỉ đối tượng tiếp nhận','给 + người + động từ','Giới từ 给 đứng TRƯỚC động từ, khác hẳn tiếng Việt đặt cho ở cuối câu. Nói 给妈妈打电话, không nói 打电话给妈妈.','我晚上给你打电话。','Tối tôi gọi điện cho bạn.',2),(60,20,'Cách đề nghị với 好吗 và 吧','Câu đề nghị + 好吗？/ 吧','Thêm 好吗 cuối câu để hỏi ý kiến người nghe một cách lịch sự, thêm 吧 để đưa ra đề nghị hoặc thúc giục nhẹ nhàng.','我们一起去吃饭，好吗？走吧！','Chúng ta cùng đi ăn nhé? Đi thôi!',3),(61,21,'Động từ năng nguyện 会 chỉ khả năng xảy ra','会 + động từ + 的','Ngoài nghĩa biết làm, 会 còn dùng để dự đoán khả năng xảy ra trong tương lai, thường thêm 的 cuối câu để tăng mức khẳng định.','天气预报说明天会下雨。','Dự báo thời tiết nói ngày mai trời sẽ mưa.',1),(62,21,'Cấu trúc 又…又… nêu hai đặc điểm','又 + tính từ A + 又 + tính từ B','Cấu trúc này nối hai tính chất cùng tồn tại và cùng sắc thái, cả hai cùng khen hoặc cùng chê chứ không trộn lẫn.','今天又闷又热，很不舒服。','Hôm nay vừa oi vừa nóng, rất khó chịu.',2),(63,21,'Câu điều kiện 如果…就…','如果 + điều kiện, 就 + kết quả','Vế điều kiện dùng 如果 hoặc 要是, vế kết quả gần như luôn có phó từ hô ứng 就. Có thể thêm 的话 sau vế điều kiện.','如果明天不下雨，我们就去公园。','Nếu ngày mai không mưa thì chúng ta đi công viên.',3),(64,22,'Bổ ngữ trạng thái với 得','Động từ + 得 + tính từ','Bổ ngữ trạng thái nhận xét mức độ của hành động. Nếu động từ có tân ngữ thì phải lặp lại động từ, hoặc đưa tân ngữ lên trước chủ ngữ.','他汉语说得很流利。','Cậu ấy nói tiếng Trung rất trôi chảy.',1),(65,22,'Cấu trúc 快要…了 chỉ việc sắp xảy ra','快要 + động từ / tính từ + 了','Cấu trúc 快要…了 và 就要…了 đều nói việc sắp xảy ra, nhưng chỉ 就要…了 mới dùng được cùng mốc thời gian cụ thể phía trước.','快要考试了，我很紧张。','Sắp thi rồi, tôi rất căng thẳng.',2),(66,22,'Cặp liên từ 虽然…但是…','虽然 + mệnh đề, 但是 + mệnh đề','Cặp liên từ nhượng bộ này luôn dùng đủ hai vế trong tiếng Trung, khác tiếng Việt thường lược bỏ một vế.','虽然汉语很难，但是很有意思。','Tuy tiếng Trung rất khó nhưng rất thú vị.',3),(67,23,'Cụm 长得 miêu tả ngoại hình','Chủ thể + 长得 + tính từ / 像 + người','Cụm 长得 chuyên dùng cho ngoại hình bẩm sinh, thường kết hợp với 像 để nói giống ai.','他长得很像他爸爸。','Cậu ấy trông rất giống bố mình.',1),(68,23,'So sánh nhất với 最','最 + tính từ + 的 + danh từ','Phó từ 最 tạo so sánh cấp cao nhất trong một phạm vi, phạm vi đó thường được nêu rõ bằng cụm chỉ nhóm đứng trước.','她是我们班最认真的学生。','Cô ấy là học sinh chăm chỉ nhất lớp chúng tôi.',2),(69,23,'Giới từ 对 nêu thái độ hướng tới ai','A + 对 + B + tính từ / động từ','Giới từ 对 nêu đối tượng mà thái độ hoặc ảnh hưởng hướng tới, cụm này đứng trước vị ngữ.','我的同事对我很热情。','Đồng nghiệp rất nhiệt tình với tôi.',3),(70,24,'Trợ từ 了 chỉ hành động hoàn thành','Động từ + 了 + tân ngữ','Trợ từ động thái 了 đứng ngay sau động từ để nói hành động đã hoàn thành. Phủ định dùng 没 và phải bỏ 了.','我吃了饭就去上班了。','Tôi ăn cơm xong là đi làm luôn.',1),(71,24,'Trợ từ 过 chỉ kinh nghiệm','Động từ + 过 + tân ngữ','Trợ từ 过 nói từng trải qua việc gì trong quá khứ, nhấn mạnh kinh nghiệm chứ không nhấn mạnh sự hoàn tất. Phủ định là 没…过.','我去过中国，没吃过北京烤鸭。','Tôi từng đi Trung Quốc, chưa từng ăn vịt quay Bắc Kinh.',2),(72,24,'Phân biệt 了, 过 và 正在','了 hoàn thành / 过 kinh nghiệm / 正在 đang diễn ra','Ba trợ từ và phó từ này đánh dấu thì và thể của hành động, là nội dung trọng tâm của kỳ thi HSK 2. Nhớ rằng tiếng Trung không chia động từ, mọi thông tin thời gian nằm ở các từ đánh dấu này.','他昨天来了，我以前见过他，现在他正在休息。','Hôm qua anh ấy đã đến, trước đây tôi từng gặp anh ấy, bây giờ anh ấy đang nghỉ.',3);
/*!40000 ALTER TABLE `lesson_grammar` ENABLE KEYS */;
UNLOCK TABLES;

