CREATE TABLE `questions` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `quiz_id` bigint NOT NULL,
  `type` varchar(30) NOT NULL DEFAULT 'SINGLE_CHOICE',
  `prompt` varchar(1000) NOT NULL,
  `prompt_pinyin` varchar(1000) DEFAULT NULL,
  `prompt_vi` varchar(1000) DEFAULT NULL,
  `audio_url` varchar(500) DEFAULT NULL,
  `image_url` varchar(500) DEFAULT NULL,
  `correct_text` varchar(500) DEFAULT NULL,
  `explanation` text,
  `points` int NOT NULL DEFAULT '1',
  `sort_order` int NOT NULL DEFAULT '0',
  `word_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_questions_quiz` (`quiz_id`),
  KEY `ix_questions_word` (`word_id`),
  CONSTRAINT `fk_questions_quiz` FOREIGN KEY (`quiz_id`) REFERENCES `quizzes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_questions_word` FOREIGN KEY (`word_id`) REFERENCES `words` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=121 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `questions`
--

LOCK TABLES `questions` WRITE;
/*!40000 ALTER TABLE `questions` DISABLE KEYS */;
INSERT INTO `questions` (`id`, `quiz_id`, `type`, `prompt`, `prompt_pinyin`, `prompt_vi`, `audio_url`, `image_url`, `correct_text`, `explanation`, `points`, `sort_order`, `word_id`) VALUES (1,1,'SINGLE_CHOICE','“谢谢!”应该怎么回答?','“Xièxie!” yīnggāi zěnme huídá?','Khi người khác nói “Cảm ơn!” thì đáp lại thế nào cho đúng?',NULL,NULL,'不客气','Khi người khác nói 谢谢 (cảm ơn), câu đáp lại chuẩn mực là 不客气 - nghĩa là “không có gì”. 对不起 là xin lỗi, 再见 là tạm biệt, còn 请问 dùng để mở lời hỏi một cách lịch sự.',1,1,NULL),(2,1,'SINGLE_CHOICE','“水”的拼音是什么?','“Shuǐ” de pīnyīn shì shénme?','Phiên âm đúng của chữ 水 là gì?',NULL,NULL,'shuǐ','Chữ 水 (nước) đọc là shuǐ, thanh 3. shuì là chữ 睡 trong 睡觉 (ngủ), còn shuī và suǐ đều không phải cách đọc của chữ này.',1,2,NULL),(3,1,'FILL_BLANK','我 ___ 中国人。','Wǒ ___ Zhōngguó rén.','Điền từ còn thiếu để câu có nghĩa “Tôi là người Trung Quốc”.',NULL,NULL,'是','Mẫu câu phán đoán “A + 是 + danh từ” dùng động từ 是 (shì) để nối chủ ngữ với danh từ chỉ danh tính. Câu hoàn chỉnh là 我是中国人。',1,3,NULL),(4,1,'SINGLE_CHOICE','“今天几号?”这个问题在问什么?','“Jīntiān jǐ hào?” zhège wèntí zài wèn shénme?','Câu hỏi 今天几号? hỏi về điều gì?',NULL,NULL,'Hỏi hôm nay là ngày mấy','Cụm 几号 (jǐ hào) dùng để hỏi ngày trong tháng. Hỏi giờ phải dùng 几点, hỏi thứ dùng 星期几, còn hỏi thời tiết dùng 天气怎么样.',1,4,NULL),(5,1,'LISTENING','Nghe và chọn từ bạn nghe được: “māma”.',NULL,'Nghe đoạn ghi âm rồi chọn chữ Hán tương ứng với âm vừa nghe.',NULL,NULL,'妈妈','Âm nghe được là māma, viết là 妈妈 (mẹ). 爸爸 đọc bàba (bố), 哥哥 đọc gēge (anh trai), 姐姐 đọc jiějie (chị gái).',1,5,NULL),(6,1,'TRANSLATION','Tôi tên là Lý Nam.',NULL,'Dịch câu tiếng Việt sau sang tiếng Trung.',NULL,NULL,'我叫李南。','Mẫu câu giới thiệu tên là “我叫 + tên”. 我 (tôi) + 叫 (tên là) + 李南 cho ra câu 我叫李南。',1,6,NULL),(7,1,'SINGLE_CHOICE','请选择正确的量词:三 ___ 人','Qǐng xuǎnzé zhèngquè de liàngcí: sān ___ rén','Chọn lượng từ đúng cho cụm “ba người”.',NULL,NULL,'个','Lượng từ thông dụng nhất để đếm người là 个: 三个人. 本 dùng cho sách, 块 dùng cho tiền hoặc miếng, 杯 dùng cho cốc nước.',1,7,NULL),(8,1,'FILL_BLANK','这是 ___ ?','Zhè shì ___?','Điền từ để hỏi “Đây là cái gì?”.',NULL,NULL,'什么','Từ để hỏi 什么 (shénme) nghĩa là “cái gì”, đặt ngay tại vị trí của thành phần cần hỏi: 这是什么?',1,8,NULL),(9,1,'LISTENING','Nghe và chọn con số bạn nghe được: “sān shí”.',NULL,'Nghe đoạn ghi âm rồi chọn con số đúng.',NULL,NULL,'三十','Cách đọc 三十 (sān shí) tương ứng số 30. Số 13 đọc ngược lại là 十三 (shí sān), 三 là 3 và 三百 là 300.',1,9,NULL),(10,1,'TRANSLATION','Hôm nay tôi rất vui.',NULL,'Dịch câu tiếng Việt sau sang tiếng Trung.',NULL,NULL,'我今天很高兴。','Trạng ngữ thời gian 今天 đứng trước vị ngữ; vị ngữ tính từ 高兴 phải có phó từ mức độ 很 đi kèm, cho ra câu 我今天很高兴。',1,10,NULL),(11,2,'SINGLE_CHOICE','“你好”应该在什么时候说?','“Nǐ hǎo” yīnggāi zài shénme shíhou shuō?','Nên nói 你好 vào lúc nào?',NULL,NULL,'Khi gặp và chào một người','你好 (nǐ hǎo) là lời chào khi gặp mặt. Lúc chia tay phải nói 再见, khi cảm ơn nói 谢谢, khi xin lỗi nói 对不起.',1,1,NULL),(12,2,'SINGLE_CHOICE','“再见”的意思是什么?','“Zàijiàn” de yìsi shì shénme?','Từ 再见 có nghĩa là gì?',NULL,NULL,'Tạm biệt','Chữ 再 (zài) nghĩa là “lại”, 见 (jiàn) nghĩa là “gặp”; ghép lại 再见 mang nghĩa “hẹn gặp lại”, tức là tạm biệt.',1,2,NULL),(13,2,'SINGLE_CHOICE','请选择正确的词:___ 叫什么名字?','Qǐng xuǎnzé zhèngquè de cí: ___ jiào shénme míngzi?','Chọn đại từ đúng để hỏi tên người đang nói chuyện với mình.',NULL,NULL,'你','Hỏi tên người đối diện phải dùng ngôi thứ hai 你: 你叫什么名字? Dùng 我 là tự hỏi chính mình, 他 là hỏi về người thứ ba, còn 们 chỉ là hậu tố tạo số nhiều.',1,3,NULL),(14,2,'SINGLE_CHOICE','“老师,您好!”中的“您”表示什么?','“Lǎoshī, nín hǎo!” zhōng de “nín” biǎoshì shénme?','Chữ 您 trong câu 老师,您好! thể hiện điều gì?',NULL,NULL,'Cách xưng hô lịch sự, tôn kính với người nghe','您 (nín) là dạng lịch sự của 你, dùng khi nói với người lớn tuổi hoặc có địa vị như thầy cô, khách hàng. Số nhiều “các bạn” phải dùng 你们.',1,4,NULL),(15,2,'FILL_BLANK','我 ___ 阮明。','Wǒ ___ Ruǎn Míng.','Điền từ còn thiếu để câu có nghĩa “Tôi tên là Nguyễn Minh”.',NULL,NULL,'叫','Mẫu câu giới thiệu tên là “我叫 + tên”. Động từ 叫 (jiào) nghĩa là “được gọi là, tên là”, nên câu đúng là 我叫阮明。',1,5,NULL),(16,2,'FILL_BLANK','很高兴 ___ 你。','Hěn gāoxìng ___ nǐ.','Điền từ còn thiếu để câu có nghĩa “Rất vui được làm quen với bạn”.',NULL,NULL,'认识','Câu xã giao chuẩn khi mới gặp là 很高兴认识你 (hěn gāoxìng rènshi nǐ). Động từ 认识 nghĩa là quen biết, làm quen.',1,6,NULL),(17,2,'TRANSLATION','Bạn khỏe không?',NULL,'Dịch câu tiếng Việt sau sang tiếng Trung.',NULL,NULL,'你好吗?','Câu hỏi được tạo bằng cách thêm trợ từ nghi vấn 吗 vào cuối câu trần thuật 你好, cho ra 你好吗?',1,7,NULL),(18,2,'TRANSLATION','Cảm ơn thầy giáo!',NULL,'Dịch câu tiếng Việt sau sang tiếng Trung.',NULL,NULL,'谢谢老师!','Động từ 谢谢 (xièxie) đặt trước đối tượng được cảm ơn, không cần thêm giới từ: 谢谢老师!',1,8,NULL),(19,2,'LISTENING','Nghe và chọn lời chào bạn nghe được: “Nǐ hǎo!”.',NULL,'Nghe đoạn ghi âm rồi chọn câu chữ Hán tương ứng.',NULL,NULL,'你好!','Âm nghe được là Nǐ hǎo, viết bằng chữ Hán là 你好 (xin chào). Các phương án còn lại đọc là zàijiàn, xièxie và duìbuqǐ.',1,9,NULL),(20,2,'LISTENING','Nghe và chọn từ chỉ nghề nghiệp bạn nghe được: “lǎoshī”.',NULL,'Nghe đoạn ghi âm rồi chọn từ chữ Hán đúng.',NULL,NULL,'老师','Âm lǎoshī viết là 老师 (giáo viên). 学生 đọc xuésheng (học sinh), 医生 đọc yīshēng (bác sĩ), 朋友 đọc péngyou (bạn bè).',1,10,NULL),(21,3,'SINGLE_CHOICE','“十二”是多少?','“Shí\'èr” shì duōshao?','Số 十二 tương ứng với số nào?',NULL,NULL,'12','Chữ 十 là 10, 二 là 2; khi 十 đứng trước thì cộng thêm, nên 十二 = 10 + 2 = 12. Số 20 phải viết là 二十.',1,1,NULL),(22,3,'SINGLE_CHOICE','“两点半”是几点?','“Liǎng diǎn bàn” shì jǐ diǎn?','Cụm 两点半 chỉ mấy giờ?',NULL,NULL,'2 giờ 30 phút','两点 là 2 giờ, 半 (bàn) nghĩa là “rưỡi”, vậy 两点半 là 2 giờ 30. Muốn nói 2 giờ 15 thì dùng 两点一刻.',1,2,NULL),(23,3,'SINGLE_CHOICE','在“两”和“二”中,哪一个用在“___ 个人”?','Zài “liǎng” hé “èr” zhōng, nǎ yí ge yòng zài “___ ge rén”?','Trong hai chữ 两 và 二, chữ nào dùng trước lượng từ 个?',NULL,NULL,'两','Trước lượng từ phải dùng 两: 两个人 (hai người). Chữ 二 chỉ dùng khi đếm số hoặc nằm trong số nhiều chữ số như 十二, 二十.',1,3,NULL),(24,3,'SINGLE_CHOICE','“星期日”是星期几?','“Xīngqīrì” shì xīngqī jǐ?','星期日 là thứ mấy trong tuần?',NULL,NULL,'Chủ nhật','星期日 (xīngqīrì) hoặc 星期天 đều có nghĩa là Chủ nhật. Thứ hai là 星期一, thứ sáu là 星期五, thứ bảy là 星期六.',1,4,NULL),(25,3,'FILL_BLANK','现在几 ___ ?','Xiànzài jǐ ___?','Điền từ còn thiếu để hỏi “Bây giờ là mấy giờ?”.',NULL,NULL,'点','Hỏi giờ trong tiếng Trung dùng cụm 几点 (jǐ diǎn), trong đó 点 là đơn vị “giờ”. Câu đúng là 现在几点?',1,5,NULL),(26,3,'FILL_BLANK','今天星期 ___ ?','Jīntiān xīngqī ___?','Điền từ còn thiếu để hỏi “Hôm nay là thứ mấy?”.',NULL,NULL,'几','Hỏi thứ trong tuần dùng cụm 星期几 (xīngqī jǐ); từ để hỏi 几 thay vào vị trí của con số cần biết.',1,6,NULL),(27,3,'TRANSLATION','Bây giờ là 8 giờ.',NULL,'Dịch câu tiếng Việt sau sang tiếng Trung.',NULL,NULL,'现在八点。','Câu chỉ giờ trong tiếng Trung không cần động từ 是, chỉ cần đặt thẳng cụm thời gian sau chủ ngữ: 现在八点。',1,7,NULL),(28,3,'TRANSLATION','Hôm nay là ngày 5 tháng 10.',NULL,'Dịch câu tiếng Việt sau sang tiếng Trung.',NULL,NULL,'今天十月五号。','Trật tự thời gian tiếng Trung đi từ đơn vị lớn đến nhỏ nên tháng đứng trước ngày: 十月五号. Câu ngày tháng cũng lược bỏ 是.',1,8,NULL),(29,3,'LISTENING','Nghe và chọn giờ bạn nghe được: “qī diǎn shí fēn”.',NULL,'Nghe đoạn ghi âm rồi chọn mốc giờ đúng.',NULL,NULL,'七点十分','七点十分 nghĩa là 7 giờ 10 phút. Mốc 10 giờ 07 phút phải đọc là 十点零七分, chú ý chữ 零 khi số phút nhỏ hơn 10.',1,9,NULL),(30,3,'LISTENING','Nghe và chọn con số bạn nghe được: “jiǔ shí bā”.',NULL,'Nghe đoạn ghi âm rồi chọn con số đúng.',NULL,NULL,'九十八','九十八 = 90 + 8 = 98. Số 89 lại đọc là 八十九, chú ý vị trí của chữ số hàng chục.',1,10,NULL),(31,4,'SINGLE_CHOICE','“爸爸”的意思是什么?','“Bàba” de yìsi shì shénme?','Từ 爸爸 có nghĩa là gì?',NULL,NULL,'Bố','爸爸 (bàba) là bố, cha. Mẹ là 妈妈 (māma), anh trai là 哥哥 (gēge), ông nội là 爷爷 (yéye).',1,1,NULL),(32,4,'SINGLE_CHOICE','“你家有几口人?”中的“口”是什么?','“Nǐ jiā yǒu jǐ kǒu rén?” zhōng de “kǒu” shì shénme?','Trong câu 你家有几口人?, chữ 口 giữ vai trò gì?',NULL,NULL,'Lượng từ đếm số người trong gia đình','Khi nói về số nhân khẩu trong nhà, người Trung Quốc dùng lượng từ 口 chứ không dùng 个: 我家有四口人 (nhà tôi có bốn người).',1,2,NULL),(33,4,'SINGLE_CHOICE','“她是我妹妹。”这句话的意思是什么?','“Tā shì wǒ mèimei.” zhè jù huà de yìsi shì shénme?','Câu 她是我妹妹。 có nghĩa là gì?',NULL,NULL,'Cô ấy là em gái tôi','妹妹 (mèimei) là em gái. Chị gái là 姐姐, em trai là 弟弟, con gái là 女儿. Đại từ 她 chỉ người nữ.',1,3,NULL),(34,4,'SINGLE_CHOICE','请选择正确的量词:一 ___ 狗','Qǐng xuǎnzé zhèngquè de liàngcí: yì ___ gǒu','Chọn lượng từ đúng cho cụm “một con chó”.',NULL,NULL,'只','只 (zhī) là lượng từ dùng cho động vật nhỏ: 一只狗, 一只猫. 本 dùng cho sách, 岁 là đơn vị tuổi chứ không phải lượng từ danh từ.',1,4,NULL),(35,4,'FILL_BLANK','我家 ___ 五口人。','Wǒ jiā ___ wǔ kǒu rén.','Điền từ còn thiếu để câu có nghĩa “Nhà tôi có 5 người”.',NULL,NULL,'有','Diễn đạt sự sở hữu hoặc tồn tại dùng động từ 有 (yǒu - có). Câu hoàn chỉnh là 我家有五口人。',1,5,NULL),(36,4,'FILL_BLANK','你女儿今年 ___ 大?','Nǐ nǚ\'ér jīnnián ___ dà?','Điền từ còn thiếu để hỏi “Con gái bạn năm nay bao nhiêu tuổi?”.',NULL,NULL,'多','Cụm 多大 (duō dà) dùng để hỏi tuổi của người đã lớn. Với trẻ nhỏ có thể hỏi 几岁: 你女儿今年几岁?',1,6,NULL),(37,4,'TRANSLATION','Đây là mẹ tôi.',NULL,'Dịch câu tiếng Việt sau sang tiếng Trung.',NULL,NULL,'这是我妈妈。','这 (zhè) nghĩa là “đây”, dùng 是 để nối với danh từ. Với quan hệ thân tộc gần gũi thường lược bỏ 的, nên nói 我妈妈 chứ không cần 我的妈妈.',1,7,NULL),(38,4,'TRANSLATION','Tôi có một người em trai.',NULL,'Dịch câu tiếng Việt sau sang tiếng Trung.',NULL,NULL,'我有一个弟弟。','Động từ 有 diễn đạt “có”; giữa số từ 一 và danh từ 弟弟 bắt buộc phải có lượng từ 个, cho ra 我有一个弟弟。',1,8,NULL),(39,4,'LISTENING','Nghe và chọn từ chỉ người thân bạn nghe được: “jiějie”.',NULL,'Nghe đoạn ghi âm rồi chọn từ chữ Hán đúng.',NULL,NULL,'姐姐','Âm jiějie viết là 姐姐 (chị gái). 妹妹 đọc mèimei (em gái), 哥哥 đọc gēge (anh trai), 弟弟 đọc dìdi (em trai).',1,9,NULL),(40,4,'LISTENING','Nghe và chọn câu bạn nghe được: “Wǒ jiā yǒu sān kǒu rén.”',NULL,'Nghe đoạn ghi âm rồi chọn câu chữ Hán đúng.',NULL,NULL,'我家有三口人。','Câu nghe được là 我家有三口人 - nhà tôi có ba người. Nếu là bốn người thì phải nghe thấy 四口人 (sì kǒu rén).',1,10,NULL),(41,5,'SINGLE_CHOICE','“米饭”是什么?','“Mǐfàn” shì shénme?','Từ 米饭 chỉ món gì?',NULL,NULL,'Cơm','米饭 (mǐfàn) là cơm nấu từ gạo. Mì sợi là 面条, nước là 水, thịt là 肉.',1,1,NULL),(42,5,'SINGLE_CHOICE','“我想喝水。”中的“喝”用于什么动作?','“Wǒ xiǎng hē shuǐ.” zhōng de “hē” yòngyú shénme dòngzuò?','Động từ 喝 trong câu 我想喝水。 dùng cho hành động nào?',NULL,NULL,'Uống (chất lỏng)','喝 (hē) là “uống”, chỉ đi với đồ uống như 水, 茶, 咖啡. Hành động ăn thức ăn dùng 吃, nhìn dùng 看, mua dùng 买.',1,2,NULL),(43,5,'SINGLE_CHOICE','请选择正确的量词:一 ___ 茶','Qǐng xuǎnzé zhèngquè de liàngcí: yì ___ chá','Chọn lượng từ đúng cho cụm “một tách trà”.',NULL,NULL,'杯','杯 (bēi) là lượng từ cho đồ uống đựng trong cốc, tách: 一杯茶, 一杯水. 只 dùng cho động vật, 本 dùng cho sách.',1,3,NULL),(44,5,'SINGLE_CHOICE','“好吃”一般用来形容什么?','“Hǎochī” yìbān yònglái xíngróng shénme?','Từ 好吃 thường dùng để miêu tả cái gì?',NULL,NULL,'Món ăn ngon','好吃 (hǎochī) là “ngon”, chỉ dùng cho thức ăn. Đồ uống ngon phải nói 好喝 (hǎohē), còn cảnh đẹp nói 好看.',1,4,NULL),(45,5,'FILL_BLANK','我想 ___ 一杯茶。','Wǒ xiǎng ___ yì bēi chá.','Điền động từ còn thiếu để câu có nghĩa “Tôi muốn uống một tách trà”.',NULL,NULL,'喝','Với đồ uống như 茶 bắt buộc dùng động từ 喝: 我想喝一杯茶。Dùng 吃 chỉ đúng khi đi với thức ăn.',1,5,NULL),(46,5,'FILL_BLANK','这个菜很好 ___ 。','Zhège cài hěn hǎo ___.','Điền từ còn thiếu để câu có nghĩa “Món này rất ngon”.',NULL,NULL,'吃','Khen món ăn ngon dùng tính từ ghép 好吃, cho ra câu 这个菜很好吃。',1,6,NULL),(47,5,'TRANSLATION','Tôi muốn ăn cơm.',NULL,'Dịch câu tiếng Việt sau sang tiếng Trung.',NULL,NULL,'我想吃米饭。','Động từ năng nguyện 想 (xiǎng - muốn) đứng trước động từ chính 吃, cho ra câu 我想吃米饭。',1,7,NULL),(48,5,'TRANSLATION','Bạn thích uống trà không?',NULL,'Dịch câu tiếng Việt sau sang tiếng Trung.',NULL,NULL,'你喜欢喝茶吗?','喜欢 + cụm động từ diễn đạt sở thích; thêm trợ từ nghi vấn 吗 ở cuối để tạo câu hỏi: 你喜欢喝茶吗?',1,8,NULL),(49,5,'LISTENING','Nghe và chọn tên đồ uống bạn nghe được: “chá”.',NULL,'Nghe đoạn ghi âm rồi chọn chữ Hán đúng.',NULL,NULL,'茶','Âm chá viết là 茶 (trà). Chú ý phân biệt với 菜 đọc cài (món ăn, rau), 车 đọc chē (xe) và 水 đọc shuǐ (nước).',1,9,NULL),(50,5,'LISTENING','Nghe và chọn câu bạn nghe được: “Wǒ bù xiǎng chī píngguǒ.”',NULL,'Nghe đoạn ghi âm rồi chọn câu chữ Hán đúng.',NULL,NULL,'我不想吃苹果。','Trong câu nghe được có phó từ phủ định 不 nên nghĩa là “tôi không muốn ăn táo”: 我不想吃苹果。',1,10,NULL),(51,6,'SINGLE_CHOICE','“多少钱?”这句话在问什么?','“Duōshao qián?” zhè jù huà zài wèn shénme?','Câu 多少钱? dùng để hỏi điều gì?',NULL,NULL,'Hỏi giá bao nhiêu tiền','Cụm 多少钱 (duōshao qián) nghĩa là “bao nhiêu tiền”, dùng để hỏi giá. Hỏi giờ dùng 几点, hỏi nơi chốn dùng 在哪儿.',1,1,NULL),(52,6,'SINGLE_CHOICE','买东西的时候,“块”表示什么?','Mǎi dōngxi de shíhou, “kuài” biǎoshì shénme?','Khi mua bán, chữ 块 chỉ điều gì?',NULL,NULL,'Đơn vị tiền tệ trong khẩu ngữ','块 (kuài) là cách nói khẩu ngữ của đơn vị tiền 元 (yuán): 十块钱 tức là 10 tệ. Trong văn viết thường ghi 元.',1,2,NULL),(53,6,'SINGLE_CHOICE','请选择正确的动词:我要 ___ 一本书。','Qǐng xuǎnzé zhèngquè de dòngcí: wǒ yào ___ yì běn shū.','Chọn động từ đúng cho câu “Tôi muốn mua một quyển sách”.',NULL,NULL,'买','买 (mǎi, thanh 3) là mua, còn 卖 (mài, thanh 4) là bán - hai chữ rất giống nhau nên phải chú ý thanh điệu. Câu cần nghĩa “mua” nên chọn 买.',1,3,NULL),(54,6,'SINGLE_CHOICE','“太贵了!”是什么意思?','“Tài guì le!” shì shénme yìsi?','Câu 太贵了! có nghĩa là gì?',NULL,NULL,'Đắt quá!','贵 (guì) nghĩa là đắt; cấu trúc 太…了 nhấn mạnh mức độ “quá”. Trái nghĩa với 贵 là 便宜 (piányi - rẻ).',1,4,NULL),(55,6,'FILL_BLANK','这本书 ___ 少钱?','Zhè běn shū ___ shao qián?','Điền từ còn thiếu để hỏi “Quyển sách này bao nhiêu tiền?”.',NULL,NULL,'多','Cụm hỏi giá cố định là 多少钱, không thể tách rời. Câu hoàn chỉnh là 这本书多少钱?',1,5,NULL),(56,6,'FILL_BLANK','我想 ___ 一些水果。','Wǒ xiǎng ___ yìxiē shuǐguǒ.','Điền động từ còn thiếu để câu có nghĩa “Tôi muốn mua một ít hoa quả”.',NULL,NULL,'买','Hành động “mua” là 买 (mǎi). Câu hoàn chỉnh là 我想买一些水果。',1,6,NULL),(57,6,'TRANSLATION','Cái này bao nhiêu tiền?',NULL,'Dịch câu tiếng Việt sau sang tiếng Trung.',NULL,NULL,'这个多少钱?','这个 nghĩa là “cái này”, đặt làm chủ ngữ rồi thêm cụm hỏi giá 多少钱 phía sau: 这个多少钱?',1,7,NULL),(58,6,'TRANSLATION','Tôi mua ba quyển sách.',NULL,'Dịch câu tiếng Việt sau sang tiếng Trung.',NULL,NULL,'我买三本书。','Sách dùng lượng từ 本; trật tự là số từ 三 + lượng từ 本 + danh từ 书, cho ra 我买三本书。',1,8,NULL),(59,6,'LISTENING','Nghe và chọn số tiền bạn nghe được: “wǔ shí kuài”.',NULL,'Nghe đoạn ghi âm rồi chọn số tiền đúng.',NULL,NULL,'五十块','五十块 nghĩa là 50 tệ. Nếu nghe 十五块 (shíwǔ kuài) thì mới là 15 tệ - chú ý thứ tự của 五 và 十.',1,9,NULL),(60,6,'LISTENING','Nghe và chọn câu bạn nghe được: “Zhège tài guì le.”',NULL,'Nghe đoạn ghi âm rồi chọn câu chữ Hán đúng.',NULL,NULL,'这个太贵了。','Câu nghe được là 这个太贵了 - cái này đắt quá. Từ trái nghĩa 便宜 (rẻ) nằm ở một phương án khác.',1,10,NULL),(61,7,'SINGLE_CHOICE','“因为…所以…”这个结构表示什么关系?','“Yīnwèi… suǒyǐ…” zhège jiégòu biǎoshì shénme guānxi?','Cấu trúc 因为…所以… biểu thị quan hệ gì?',NULL,NULL,'Nguyên nhân - kết quả','因为 (yīnwèi) nêu nguyên nhân, 所以 (suǒyǐ) nêu kết quả: 因为下雨,所以我没去 - vì trời mưa nên tôi không đi.',1,1,NULL),(62,7,'SINGLE_CHOICE','“我已经吃过饭了。”中的“过”表示什么?','“Wǒ yǐjīng chī guo fàn le.” zhōng de “guo” biǎoshì shénme?','Trợ từ 过 trong câu 我已经吃过饭了。 biểu thị điều gì?',NULL,NULL,'Việc đã từng trải qua hoặc đã hoàn tất','过 (guo) là trợ từ động thái đặt sau động từ, chỉ kinh nghiệm hoặc việc đã trải qua. Kết hợp 已经…了 nhấn mạnh nghĩa “đã… rồi”.',1,2,NULL),(63,7,'SINGLE_CHOICE','比较句“他比我高”的意思是什么?','Bǐjiào jù “tā bǐ wǒ gāo” de yìsi shì shénme?','Câu so sánh 他比我高 có nghĩa là gì?',NULL,NULL,'Anh ấy cao hơn tôi','Cấu trúc so sánh “A + 比 + B + tính từ” nghĩa là A hơn B ở mặt đó, nên 他比我高 nghĩa là anh ấy cao hơn tôi.',1,3,NULL),(64,7,'SINGLE_CHOICE','请选择正确的字:我听 ___ 懂。','Qǐng xuǎnzé zhèngquè de zì: wǒ tīng ___ dǒng.','Chọn chữ đúng để tạo bổ ngữ khả năng “nghe hiểu được”.',NULL,NULL,'得','Bổ ngữ khả năng dạng khẳng định dùng 得 nối giữa động từ và bổ ngữ: 听得懂 (nghe hiểu được). 的 dùng với định ngữ, 地 dùng với trạng ngữ.',1,4,NULL),(65,7,'FILL_BLANK','他正 ___ 看电视呢。','Tā zhèng ___ kàn diànshì ne.','Điền từ còn thiếu để câu có nghĩa “Anh ấy đang xem tivi”.',NULL,NULL,'在','Cấu trúc 正在… 呢 diễn đạt hành động đang tiếp diễn ngay lúc nói. Câu hoàn chỉnh là 他正在看电视呢。',1,5,NULL),(66,7,'FILL_BLANK','今天 ___ 昨天冷。','Jīntiān ___ zuótiān lěng.','Điền từ còn thiếu để câu có nghĩa “Hôm nay lạnh hơn hôm qua”.',NULL,NULL,'比','So sánh hơn dùng giới từ 比 đặt giữa hai đối tượng: A 比 B + tính từ, cho ra 今天比昨天冷。',1,6,NULL),(67,7,'TRANSLATION','Tôi đã học tiếng Trung hai năm rồi.',NULL,'Dịch câu tiếng Việt sau sang tiếng Trung.',NULL,NULL,'我学汉语两年了。','Bổ ngữ thời lượng 两年 đặt sau động từ 学; trợ từ 了 cuối câu cho biết việc học kéo dài đến hiện tại: 我学汉语两年了。',1,7,NULL),(68,7,'TRANSLATION','Vì trời mưa nên tôi không đi.',NULL,'Dịch câu tiếng Việt sau sang tiếng Trung.',NULL,NULL,'因为下雨,所以我没去。','Cặp liên từ 因为…所以… nối vế nguyên nhân với vế kết quả; phủ định việc đã xảy ra trong quá khứ dùng 没 chứ không dùng 不.',1,8,NULL),(69,7,'LISTENING','Nghe và chọn câu bạn nghe được: “Wǒ zuótiān qù le yīyuàn.”',NULL,'Nghe đoạn ghi âm rồi chọn câu chữ Hán đúng.',NULL,NULL,'我昨天去了医院。','昨天 là hôm qua, 医院 là bệnh viện, trợ từ 了 sau động từ cho biết hành động đã hoàn thành: 我昨天去了医院。',1,9,NULL),(70,7,'LISTENING','Nghe và chọn từ chỉ thời tiết bạn nghe được: “xiàyǔ”.',NULL,'Nghe đoạn ghi âm rồi chọn từ chữ Hán đúng.',NULL,NULL,'下雨','Âm xiàyǔ viết là 下雨 (trời mưa). 下雪 (xiàxuě) là tuyết rơi, 晴天 (qíngtiān) là trời nắng, 阴天 (yīntiān) là trời âm u.',1,10,NULL),(71,8,'SINGLE_CHOICE','“上午”指一天中的什么时间?','“Shàngwǔ” zhǐ yì tiān zhōng de shénme shíjiān?','Từ 上午 chỉ khoảng thời gian nào trong ngày?',NULL,NULL,'Buổi sáng, trước 12 giờ trưa','上午 (shàngwǔ) là buổi sáng trước giờ trưa. Buổi chiều là 下午, buổi tối là 晚上, giữa trưa là 中午.',1,1,NULL),(72,8,'SINGLE_CHOICE','“分钟”和“点”有什么区别?','“Fēnzhōng” hé “diǎn” yǒu shénme qūbié?','Sự khác nhau giữa 分钟 và 点 là gì?',NULL,NULL,'点 chỉ thời điểm (mấy giờ), 分钟 chỉ độ dài thời gian (số phút)','八点 là 8 giờ - một thời điểm; 二十分钟 là 20 phút - một khoảng thời gian. Muốn nói phút của một giờ cụ thể thì dùng 分: 八点十分.',1,2,NULL),(73,8,'SINGLE_CHOICE','请选择正确的词:我 ___ 七点起床。','Qǐng xuǎnzé zhèngquè de cí: wǒ ___ qī diǎn qǐchuáng.','Chọn từ đúng cho câu “Ngày nào tôi cũng dậy lúc 7 giờ”.',NULL,NULL,'每天','每天 (měitiān) nghĩa là “mỗi ngày, hằng ngày”, phù hợp để diễn đạt thói quen lặp lại: 我每天七点起床。',1,3,NULL),(74,8,'SINGLE_CHOICE','“从…到…”表示什么?','“Cóng… dào…” biǎoshì shénme?','Cấu trúc 从…到… biểu thị điều gì?',NULL,NULL,'Từ … đến …, chỉ điểm đầu và điểm cuối','从八点到十点 nghĩa là “từ 8 giờ đến 10 giờ”. Cấu trúc này cũng dùng cho không gian: 从家到学校 - từ nhà đến trường.',1,4,NULL),(75,8,'FILL_BLANK','会议 ___ 九点开始。','Huìyì ___ jiǔ diǎn kāishǐ.','Điền từ còn thiếu để câu có nghĩa “Cuộc họp bắt đầu từ lúc 9 giờ”.',NULL,NULL,'从','Điểm khởi đầu của thời gian được dẫn ra bằng giới từ 从 (cóng): 会议从九点开始。',1,5,NULL),(76,8,'FILL_BLANK','我昨天睡了八个 ___ 。','Wǒ zuótiān shuì le bā ge ___.','Điền từ còn thiếu để câu có nghĩa “Hôm qua tôi ngủ tám tiếng”.',NULL,NULL,'小时','小时 (xiǎoshí) là đơn vị “tiếng đồng hồ”, luôn đi cùng lượng từ 个: 八个小时. Đây là bổ ngữ thời lượng đặt sau động từ.',1,6,NULL),(77,8,'TRANSLATION','Ngày nào tôi cũng dậy lúc 6 rưỡi.',NULL,'Dịch câu tiếng Việt sau sang tiếng Trung.',NULL,NULL,'我每天六点半起床。','Trạng ngữ thời gian 每天六点半 đứng trước động từ 起床, không được đặt sau: 我每天六点半起床。',1,7,NULL),(78,8,'TRANSLATION','Ngày mai tôi phải đi làm.',NULL,'Dịch câu tiếng Việt sau sang tiếng Trung.',NULL,NULL,'明天我要上班。','Động từ năng nguyện 要 (yào) diễn đạt “phải, sẽ”, đứng ngay trước động từ 上班 (đi làm): 明天我要上班。',1,8,NULL),(79,8,'LISTENING','Nghe và chọn thời điểm bạn nghe được: “xiàwǔ sān diǎn”.',NULL,'Nghe đoạn ghi âm rồi chọn mốc thời gian đúng.',NULL,NULL,'下午三点','下午 là buổi chiều, 三点 là 3 giờ, vậy đáp án là 3 giờ chiều. Buổi sáng phải là 上午 hoặc 早上.',1,9,NULL),(80,8,'LISTENING','Nghe và chọn câu bạn nghe được: “Wǒ měitiān liù diǎn bàn qǐchuáng.”',NULL,'Nghe đoạn ghi âm rồi chọn câu chữ Hán đúng.',NULL,NULL,'我每天六点半起床。','Câu nghe có 六点半 (6 giờ rưỡi) và động từ 起床 (thức dậy). Nếu là 睡觉 thì nghĩa lại thành “đi ngủ”.',1,10,NULL),(81,9,'SINGLE_CHOICE','“上班”的意思是什么?','“Shàngbān” de yìsi shì shénme?','Từ 上班 có nghĩa là gì?',NULL,NULL,'Đi làm','上班 (shàngbān) là đi làm, vào ca. Tan làm là 下班, đi học là 上课 hoặc 上学.',1,1,NULL),(82,9,'SINGLE_CHOICE','“他在公司工作。”中的“在”起什么作用?','“Tā zài gōngsī gōngzuò.” zhōng de “zài” qǐ shénme zuòyòng?','Chữ 在 trong câu 他在公司工作。 giữ vai trò gì?',NULL,NULL,'Giới từ chỉ nơi chốn (ở, tại)','Cấu trúc 在 + địa điểm + động từ tạo thành trạng ngữ nơi chốn đặt trước động từ chính: 他在公司工作 - anh ấy làm việc ở công ty.',1,2,NULL),(83,9,'SINGLE_CHOICE','请选择正确的词:在医院工作的人叫 ___ 。','Qǐng xuǎnzé zhèngquè de cí: zài yīyuàn gōngzuò de rén jiào ___.','Chọn từ đúng: Người làm việc trong bệnh viện được gọi là gì?',NULL,NULL,'医生','医生 (yīshēng) là bác sĩ, làm việc trong 医院 (bệnh viện). 老师 dạy học ở trường, 服务员 phục vụ ở nhà hàng.',1,3,NULL),(84,9,'SINGLE_CHOICE','“我觉得这个工作很有意思。”中的“觉得”表示什么?','“Wǒ juéde zhège gōngzuò hěn yǒu yìsi.” zhōng de “juéde” biǎoshì shénme?','Từ 觉得 trong câu trên biểu thị điều gì?',NULL,NULL,'Nêu ý kiến, cảm nhận của người nói','觉得 (juéde) nghĩa là “cảm thấy, thấy rằng”, dùng để nêu nhận định. Lưu ý chữ 觉 trong 睡觉 lại đọc là jiào.',1,4,NULL),(85,9,'FILL_BLANK','他 ___ 公司工作。','Tā ___ gōngsī gōngzuò.','Điền từ còn thiếu để câu có nghĩa “Anh ấy làm việc ở công ty”.',NULL,NULL,'在','Giới từ 在 dẫn ra nơi chốn và phải đứng trước động từ chính: 他在公司工作。',1,5,NULL),(86,9,'FILL_BLANK','我下班以后 ___ 家。','Wǒ xiàbān yǐhòu ___ jiā.','Điền động từ còn thiếu để câu có nghĩa “Sau khi tan làm tôi về nhà”.',NULL,NULL,'回','回家 (huí jiā) nghĩa là về nhà; 以后 nghĩa là “sau khi”. Câu hoàn chỉnh là 我下班以后回家。',1,6,NULL),(87,9,'TRANSLATION','Anh ấy là bác sĩ.',NULL,'Dịch câu tiếng Việt sau sang tiếng Trung.',NULL,NULL,'他是医生。','Câu phán đoán dùng 是 nối chủ ngữ với danh từ chỉ nghề nghiệp, không cần thêm lượng từ: 他是医生。',1,7,NULL),(88,9,'TRANSLATION','Hôm nay tôi rất bận.',NULL,'Dịch câu tiếng Việt sau sang tiếng Trung.',NULL,NULL,'我今天很忙。','Vị ngữ tính từ 忙 cần phó từ mức độ 很 đi kèm và không dùng 是; trạng ngữ thời gian 今天 đứng trước: 我今天很忙。',1,8,NULL),(89,9,'LISTENING','Nghe và chọn tên nghề nghiệp bạn nghe được: “fúwùyuán”.',NULL,'Nghe đoạn ghi âm rồi chọn từ chữ Hán đúng.',NULL,NULL,'服务员','Âm fúwùyuán viết là 服务员 (nhân viên phục vụ). 老师 đọc lǎoshī, 医生 đọc yīshēng, 学生 đọc xuésheng.',1,9,NULL),(90,9,'LISTENING','Nghe và chọn câu bạn nghe được: “Tā zài xuéxiào gōngzuò.”',NULL,'Nghe đoạn ghi âm rồi chọn câu chữ Hán đúng.',NULL,NULL,'他在学校工作。','学校 là trường học, 工作 là làm việc, nên câu đúng là 他在学校工作。Nếu là 学习 thì nghĩa thành “học tập ở trường”.',1,10,NULL),(91,10,'SINGLE_CHOICE','“我生病了。”是什么意思?','“Wǒ shēngbìng le.” shì shénme yìsi?','Câu 我生病了。 có nghĩa là gì?',NULL,NULL,'Tôi bị ốm rồi','生病 (shēngbìng) nghĩa là bị ốm, mắc bệnh; trợ từ 了 cuối câu cho biết trạng thái mới xuất hiện: 我生病了 - tôi bị ốm rồi.',1,1,NULL),(92,10,'SINGLE_CHOICE','身体不舒服的时候应该去哪里?','Shēntǐ bù shūfu de shíhou yīnggāi qù nǎlǐ?','Khi trong người khó chịu thì nên đến đâu?',NULL,NULL,'医院','不舒服 (bù shūfu) nghĩa là khó chịu, không khỏe; khi đó nên đến 医院 (bệnh viện) để khám bác sĩ.',1,2,NULL),(93,10,'SINGLE_CHOICE','“吃药”用越南语怎么说更准确?','“Chī yào” yòng Yuènányǔ zěnme shuō gèng zhǔnquè?','Cụm 吃药 dịch sang tiếng Việt thế nào cho đúng?',NULL,NULL,'Uống thuốc','Tiếng Trung nói 吃药 (nghĩa đen là “ăn thuốc”) nhưng tiếng Việt phải nói “uống thuốc”. Đây là điểm khác biệt cần nhớ khi dịch.',1,3,NULL),(94,10,'SINGLE_CHOICE','请选择正确的词:医生说我要多 ___ 。','Qǐng xuǎnzé zhèngquè de cí: yīshēng shuō wǒ yào duō ___.','Chọn từ đúng cho câu “Bác sĩ nói tôi phải nghỉ ngơi nhiều hơn”.',NULL,NULL,'休息','休息 (xiūxi) nghĩa là nghỉ ngơi, phù hợp với lời khuyên của bác sĩ: 医生说我要多休息。运动 là vận động, 工作 là làm việc.',1,4,NULL),(95,10,'FILL_BLANK','我头 ___ ,想去医院。','Wǒ tóu ___, xiǎng qù yīyuàn.','Điền từ còn thiếu để câu có nghĩa “Tôi đau đầu, muốn đi bệnh viện”.',NULL,NULL,'疼','疼 (téng) nghĩa là đau; 头疼 là đau đầu. Câu hoàn chỉnh là 我头疼,想去医院。',1,5,NULL),(96,10,'FILL_BLANK','你要多 ___ 水。','Nǐ yào duō ___ shuǐ.','Điền động từ còn thiếu để câu có nghĩa “Bạn phải uống nhiều nước”.',NULL,NULL,'喝','Với danh từ 水 phải dùng động từ 喝 (uống); cấu trúc 多 + động từ nghĩa là “làm việc gì nhiều hơn”: 你要多喝水。',1,6,NULL),(97,10,'TRANSLATION','Tôi bị cảm rồi.',NULL,'Dịch câu tiếng Việt sau sang tiếng Trung.',NULL,NULL,'我感冒了。','感冒 (gǎnmào) là bị cảm; trợ từ 了 cuối câu diễn đạt trạng thái mới xuất hiện, cho ra 我感冒了。',1,7,NULL),(98,10,'TRANSLATION','Bác sĩ nói tôi cần nghỉ ngơi.',NULL,'Dịch câu tiếng Việt sau sang tiếng Trung.',NULL,NULL,'医生说我要休息。','Động từ 说 dẫn ra lời nói gián tiếp, còn 要 diễn đạt ý “cần, phải”: 医生说我要休息。',1,8,NULL),(99,10,'LISTENING','Nghe và chọn từ bạn nghe được: “yīyuàn”.',NULL,'Nghe đoạn ghi âm rồi chọn từ chữ Hán đúng.',NULL,NULL,'医院','Âm yīyuàn viết là 医院 (bệnh viện). Chú ý phân biệt với 医生 (yīshēng - bác sĩ), hai từ chỉ khác nhau ở âm tiết thứ hai.',1,9,NULL),(100,10,'LISTENING','Nghe và chọn câu bạn nghe được: “Wǒ jīntiān shēntǐ bù shūfu.”',NULL,'Nghe đoạn ghi âm rồi chọn câu chữ Hán đúng.',NULL,NULL,'我今天身体不舒服。','Cụm 身体不舒服 nghĩa là “trong người khó chịu”; 今天 là hôm nay, nên câu đúng là 我今天身体不舒服。',1,10,NULL),(101,11,'SINGLE_CHOICE','“坐飞机”的意思是什么?','“Zuò fēijī” de yìsi shì shénme?','Cụm 坐飞机 có nghĩa là gì?',NULL,NULL,'Đi máy bay','Cấu trúc 坐 + phương tiện nghĩa là “đi bằng…”: 坐飞机 (đi máy bay), 坐火车 (đi tàu hỏa), 坐公共汽车 (đi xe buýt).',1,1,NULL),(102,11,'SINGLE_CHOICE','“我要去北京旅游。”中的“旅游”是什么意思?','“Wǒ yào qù Běijīng lǚyóu.” zhōng de “lǚyóu” shì shénme yìsi?','Từ 旅游 trong câu trên có nghĩa là gì?',NULL,NULL,'Du lịch','旅游 (lǚyóu) nghĩa là đi du lịch, tham quan: 去北京旅游 - đi du lịch Bắc Kinh.',1,2,NULL),(103,11,'SINGLE_CHOICE','问路时,“火车站怎么走?”是在问什么?','Wèn lù shí, “huǒchēzhàn zěnme zǒu?” shì zài wèn shénme?','Câu 火车站怎么走? dùng để hỏi điều gì?',NULL,NULL,'Hỏi đường đến nhà ga tàu hỏa','Cụm 怎么走 (zěnme zǒu) nghĩa là “đi thế nào”, dùng để hỏi đường: 火车站怎么走? - Đến ga tàu đi đường nào?',1,3,NULL),(104,11,'SINGLE_CHOICE','请选择正确的量词:一 ___ 出租车','Qǐng xuǎnzé zhèngquè de liàngcí: yí ___ chūzūchē','Chọn lượng từ đúng cho cụm “một chiếc taxi”.',NULL,NULL,'辆','辆 (liàng) là lượng từ dành cho xe cộ: 一辆出租车, 一辆汽车. 张 dùng cho vật phẳng, 件 dùng cho quần áo và sự việc.',1,4,NULL),(105,11,'FILL_BLANK','我 ___ 火车去上海。','Wǒ ___ huǒchē qù Shànghǎi.','Điền động từ còn thiếu để câu có nghĩa “Tôi đi tàu hỏa đến Thượng Hải”.',NULL,NULL,'坐','Đi bằng phương tiện có thể ngồi được thì dùng động từ 坐: 我坐火车去上海。',1,5,NULL),(106,11,'FILL_BLANK','从我家 ___ 机场很远。','Cóng wǒ jiā ___ jīchǎng hěn yuǎn.','Điền từ còn thiếu để câu có nghĩa “Từ nhà tôi đến sân bay rất xa”.',NULL,NULL,'到','Cặp giới từ 从…到… chỉ điểm đầu và điểm cuối của quãng đường: 从我家到机场很远。',1,6,NULL),(107,11,'TRANSLATION','Tôi muốn đi Bắc Kinh du lịch.',NULL,'Dịch câu tiếng Việt sau sang tiếng Trung.',NULL,NULL,'我想去北京旅游。','Trật tự là 想 (muốn) + 去 + địa điểm + mục đích, nên câu đúng là 我想去北京旅游。',1,7,NULL),(108,11,'TRANSLATION','Nhà ga tàu hỏa cách đây có xa không?',NULL,'Dịch câu tiếng Việt sau sang tiếng Trung.',NULL,NULL,'火车站离这儿远吗?','Giới từ 离 (lí) dùng để nêu khoảng cách giữa hai điểm: A 离 B 远吗? Câu đúng là 火车站离这儿远吗?',1,8,NULL),(109,11,'LISTENING','Nghe và chọn phương tiện bạn nghe được: “gōnggòng qìchē”.',NULL,'Nghe đoạn ghi âm rồi chọn từ chữ Hán đúng.',NULL,NULL,'公共汽车','公共汽车 (gōnggòng qìchē) là xe buýt. 出租车 là taxi, 火车 là tàu hỏa, 飞机 là máy bay.',1,9,NULL),(110,11,'LISTENING','Nghe và chọn câu bạn nghe được: “Wǒ zuò fēijī qù Běijīng.”',NULL,'Nghe đoạn ghi âm rồi chọn câu chữ Hán đúng.',NULL,NULL,'我坐飞机去北京。','飞机 là máy bay, 北京 là Bắc Kinh, nên câu đúng là 我坐飞机去北京。Nếu nghe 火车 thì phương tiện lại là tàu hỏa.',1,10,NULL),(111,12,'SINGLE_CHOICE','“今天天气怎么样?”这句话在问什么?','“Jīntiān tiānqì zěnmeyàng?” zhè jù huà zài wèn shénme?','Câu 今天天气怎么样? dùng để hỏi điều gì?',NULL,NULL,'Hỏi thời tiết hôm nay thế nào','天气 (tiānqì) là thời tiết, 怎么样 dùng để hỏi “thế nào”, nên cả câu hỏi về tình hình thời tiết hôm nay.',1,1,NULL),(112,12,'SINGLE_CHOICE','“外面在下雨。”是什么意思?','“Wàimiàn zài xiàyǔ.” shì shénme yìsi?','Câu 外面在下雨。 có nghĩa là gì?',NULL,NULL,'Bên ngoài đang mưa','Phó từ 在 đặt trước động từ chỉ hành động đang diễn ra, 下雨 nghĩa là mưa, nên câu này nghĩa là “bên ngoài đang mưa”.',1,2,NULL),(113,12,'SINGLE_CHOICE','请选择正确的词:今天很 ___ ,我要多穿一点。','Qǐng xuǎnzé zhèngquè de cí: jīntiān hěn ___, wǒ yào duō chuān yìdiǎn.','Chọn từ đúng cho câu “Hôm nay rất ___, tôi phải mặc thêm áo”.',NULL,NULL,'冷','Phải mặc thêm quần áo là vì trời lạnh, nên chọn 冷 (lěng). 热 là nóng, 快 là nhanh, 累 là mệt - đều không hợp ngữ cảnh.',1,3,NULL),(114,12,'SINGLE_CHOICE','“我最喜欢踢足球。”中的“最”表示什么?','“Wǒ zuì xǐhuan tī zúqiú.” zhōng de “zuì” biǎoshì shénme?','Chữ 最 trong câu 我最喜欢踢足球。 biểu thị điều gì?',NULL,NULL,'Mức độ cao nhất, nghĩa là “nhất”','最 (zuì) là phó từ chỉ mức độ cao nhất: 最喜欢 nghĩa là “thích nhất”. Cụm 踢足球 nghĩa là chơi bóng đá.',1,4,NULL),(115,12,'FILL_BLANK','今天比昨天 ___ 。','Jīntiān bǐ zuótiān ___.','Điền từ còn thiếu để câu có nghĩa “Hôm nay nóng hơn hôm qua”.',NULL,NULL,'热','Câu so sánh “A 比 B + tính từ” đặt tính từ ở cuối: 今天比昨天热 - hôm nay nóng hơn hôm qua.',1,5,NULL),(116,12,'FILL_BLANK','我喜欢 ___ 音乐。','Wǒ xǐhuan ___ yīnyuè.','Điền động từ còn thiếu để câu có nghĩa “Tôi thích nghe nhạc”.',NULL,NULL,'听','Nghe nhạc là cụm cố định 听音乐 (tīng yīnyuè), trong đó 听 là động từ “nghe”.',1,6,NULL),(117,12,'TRANSLATION','Hôm nay trời rất lạnh.',NULL,'Dịch câu tiếng Việt sau sang tiếng Trung.',NULL,NULL,'今天很冷。','Câu vị ngữ tính từ không dùng 是; tính từ 冷 đi kèm phó từ mức độ 很, cho ra câu 今天很冷。',1,7,NULL),(118,12,'TRANSLATION','Tôi thích chơi bóng đá.',NULL,'Dịch câu tiếng Việt sau sang tiếng Trung.',NULL,NULL,'我喜欢踢足球。','喜欢 + cụm động từ diễn đạt sở thích; “chơi bóng đá” trong tiếng Trung dùng động từ 踢 (đá): 我喜欢踢足球。',1,8,NULL),(119,12,'LISTENING','Nghe và chọn từ chỉ thời tiết bạn nghe được: “xiàxuě”.',NULL,'Nghe đoạn ghi âm rồi chọn từ chữ Hán đúng.',NULL,NULL,'下雪','Âm xiàxuě viết là 下雪 (tuyết rơi). Còn 下雨 (xiàyǔ) mới là trời mưa - hai từ chỉ khác nhau ở âm tiết thứ hai.',1,9,NULL),(120,12,'LISTENING','Nghe và chọn câu bạn nghe được: “Jīntiān tiānqì hěn hǎo.”',NULL,'Nghe đoạn ghi âm rồi chọn câu chữ Hán đúng.',NULL,NULL,'今天天气很好。','Câu nghe được là 今天天气很好 - hôm nay thời tiết rất đẹp. Nếu có phó từ 不 thì nghĩa sẽ ngược lại.',1,10,NULL);
