LOCK TABLES `quizzes` WRITE;
/*!40000 ALTER TABLE `quizzes` DISABLE KEYS */;
INSERT INTO `quizzes` (`id`, `slug`, `title`, `description`, `course_id`, `lesson_id`, `hsk_level`, `time_limit_seconds`, `pass_score`, `published`, `created_at`, `updated_at`) VALUES (1,'kiem-tra-tong-hop-hsk1','Kiểm tra tổng hợp HSK 1','Bài kiểm tra tổng hợp toàn bộ kiến thức HSK 1: chào hỏi, số đếm, thời gian, gia đình, ăn uống và mua sắm. Làm bài trong 10 phút, đạt từ 60 điểm trở lên là qua.',1,NULL,1,600,60,_binary '','2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(2,'kiem-tra-bai-1-chao-hoi','Kiểm tra Bài 1: Chào hỏi và giới thiệu','Ôn tập các mẫu câu chào hỏi, hỏi tên và giới thiệu bản thân bằng tiếng Trung ở trình độ HSK 1.',1,NULL,1,600,60,_binary '','2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(3,'kiem-tra-bai-2-so-dem-thoi-gian','Kiểm tra Bài 2: Số đếm và thời gian','Ôn tập số đếm từ 1 đến 100, cách hỏi giờ, hỏi ngày tháng và thứ trong tuần bằng tiếng Trung.',1,NULL,1,600,60,_binary '','2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(4,'kiem-tra-bai-3-gia-dinh','Kiểm tra Bài 3: Gia đình','Ôn tập từ vựng về các thành viên trong gia đình, lượng từ đếm người và mẫu câu nói về số nhân khẩu.',1,NULL,1,600,60,_binary '','2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(5,'kiem-tra-bai-4-an-uong','Kiểm tra Bài 4: Ăn uống','Ôn tập từ vựng món ăn, đồ uống, phân biệt động từ 吃 và 喝 cùng mẫu câu diễn đạt mong muốn.',1,NULL,1,600,60,_binary '','2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(6,'kiem-tra-bai-5-mua-sam','Kiểm tra Bài 5: Mua sắm và giá cả','Ôn tập cách hỏi giá, đơn vị tiền tệ, phân biệt 买 và 卖 cùng các lượng từ thường gặp khi mua hàng.',1,NULL,1,600,60,_binary '','2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(7,'kiem-tra-tong-hop-hsk2','Kiểm tra tổng hợp HSK 2','Bài kiểm tra tổng hợp trình độ HSK 2: câu so sánh với 比, trợ từ 了 và 过, cấu trúc 因为…所以… và hành động đang tiếp diễn.',2,NULL,2,600,60,_binary '','2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(8,'kiem-tra-bai-13-thoi-gian-lich-trinh','Kiểm tra Bài 13: Thời gian và lịch trình','Ôn tập cách nói buổi trong ngày, độ dài thời gian, cấu trúc 从…到… và thói quen sinh hoạt hằng ngày.',2,NULL,2,600,60,_binary '','2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(9,'kiem-tra-bai-14-cong-viec-hoc-tap','Kiểm tra Bài 14: Công việc và học tập','Ôn tập từ vựng nghề nghiệp, mẫu câu 在 + nơi chốn + động từ và cách nêu ý kiến với 觉得.',2,NULL,2,600,60,_binary '','2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(10,'kiem-tra-bai-15-suc-khoe','Kiểm tra Bài 15: Sức khỏe','Ôn tập từ vựng về bệnh tật, khám bệnh, lời khuyên sức khỏe và mẫu câu 我 + 生病/感冒 + 了.',2,NULL,2,600,60,_binary '','2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(11,'kiem-tra-bai-16-du-lich-giao-thong','Kiểm tra Bài 16: Du lịch và giao thông','Ôn tập từ vựng phương tiện đi lại, cách hỏi đường, giới từ 离 và cấu trúc 坐 + phương tiện.',2,NULL,2,600,60,_binary '','2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(12,'kiem-tra-bai-17-thoi-tiet-so-thich','Kiểm tra Bài 17: Thời tiết và sở thích','Ôn tập cách hỏi và miêu tả thời tiết, câu so sánh 比 và cách diễn đạt sở thích với 喜欢 / 最喜欢.',2,NULL,2,600,60,_binary '','2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000');
/*!40000 ALTER TABLE `quizzes` ENABLE KEYS */;
UNLOCK TABLES;

