INSERT INTO `topics` (`id`, `slug`, `name_vi`, `name_zh`, `description`, `icon`, `sort_order`, `created_at`, `updated_at`) VALUES (1,'chao-hoi','Chào hỏi','问候','Các mẫu câu chào hỏi, làm quen, giới thiệu bản thân và tạm biệt trong giao tiếp hằng ngày.','👋',1,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(2,'gia-dinh','Gia đình','家庭','Từ vựng về các thành viên trong gia đình, quan hệ họ hàng và cách xưng hô.','👨‍👩‍👧',2,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(3,'so-dem','Số đếm','数字','Chữ số, cách đọc số, đếm tuổi, đếm tiền và các lượng từ cơ bản đi kèm số.','🔢',3,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(4,'thoi-gian','Thời gian','时间','Ngày, tháng, năm, thứ, giờ giấc và các trạng từ chỉ thời gian thường gặp.','🕐',4,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(5,'mau-sac','Màu sắc','颜色','Tên các màu sắc cơ bản và cách miêu tả màu của đồ vật.','🎨',5,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(6,'do-an','Đồ ăn và thức uống','饮食','Món ăn, đồ uống, hoa quả, cách gọi món và nói về khẩu vị.','🍜',6,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(7,'hoc-tap','Học tập','学习','Từ vựng về trường lớp, thầy cô, bạn học, sách vở và hoạt động học tiếng Trung.','📚',7,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(8,'cong-viec','Công việc','工作','Nghề nghiệp, nơi làm việc, đồng nghiệp và các hoạt động thường ngày ở công ty.','💼',8,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(9,'mua-sam','Mua sắm','购物','Đi chợ, siêu thị, hỏi giá, mặc cả, thanh toán và mô tả hàng hoá.','🛒',9,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(10,'giao-thong','Giao thông','交通','Phương tiện đi lại, hỏi đường, chỉ đường và các địa điểm công cộng.','🚌',10,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(11,'thoi-tiet','Thời tiết','天气','Các hiện tượng thời tiết, bốn mùa, nhiệt độ và cách hỏi đáp về thời tiết.','☀️',11,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(12,'co-the-suc-khoe','Cơ thể và sức khoẻ','身体与健康','Bộ phận cơ thể, triệu chứng bệnh, đi khám bác sĩ và lời khuyên giữ gìn sức khoẻ.','🩺',12,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(13,'nha-cua','Nhà cửa','房屋','Các phòng trong nhà, đồ đạc nội thất và hoạt động sinh hoạt tại nhà.','🏠',13,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(14,'dong-tu-thong-dung','Động từ thông dụng','常用动词','Nhóm động từ xuất hiện nhiều nhất ở trình độ HSK1 - HSK2, dùng cho mọi chủ đề.','⚡',14,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000'),(15,'hu-tu-ngu-phap','Hư từ & ngữ pháp','虚词与语法','Liên từ, phó từ, trợ từ và đại từ nghi vấn - nhóm từ công cụ dùng để nối câu và diễn đạt quan hệ ngữ pháp.','grammar',15,'2026-01-01 00:00:00.000000','2026-01-01 00:00:00.000000');
/*!40000 ALTER TABLE `topics` ENABLE KEYS */;
