INSERT INTO `word_examples` (`id`, `word_id`, `sentence_zh`, `sentence_pinyin`, `sentence_vi`, `audio_url`, `sort_order`) VALUES (1,1,'我是学生。','Wǒ shì xuésheng.','Tôi là học sinh.',NULL,0),(2,2,'你好吗？','Nǐ hǎo ma?','Bạn có khỏe không?',NULL,0),(3,3,'他是我的朋友。','Tā shì wǒ de péngyou.','Anh ấy là bạn của tôi.',NULL,0),(4,4,'她是老师。','Tā shì lǎoshī.','Cô ấy là giáo viên.',NULL,0),(5,5,'我们是同学。','Wǒmen shì tóngxué.','Chúng tôi là bạn học.',NULL,0),(6,6,'他是谁？','Tā shì shéi?','Anh ấy là ai vậy?',NULL,0),(7,7,'你叫什么名字？','Nǐ jiào shénme míngzi?','Bạn tên là gì?',NULL,0),(8,8,'你是哪国人？','Nǐ shì nǎ guó rén?','Bạn là người nước nào?',NULL,0),(9,9,'你在哪儿？','Nǐ zài nǎr?','Bạn đang ở đâu?',NULL,0),(10,10,'这是我的书。','Zhè shì wǒ de shū.','Đây là quyển sách của tôi.',NULL,0),(11,11,'那是他的家。','Nà shì tā de jiā.','Kia là nhà của anh ấy.',NULL,0),(12,12,'我家有四个人。','Wǒ jiā yǒu sì ge rén.','Nhà tôi có bốn người.',NULL,0),(13,13,'我有一个儿子。','Wǒ yǒu yí ge érzi.','Tôi có một người con trai.',NULL,0),(14,14,'我有二十块钱。','Wǒ yǒu èrshí kuài qián.','Tôi có hai mươi tệ.',NULL,0),(15,15,'现在是三点。','Xiànzài shì sān diǎn.','Bây giờ là ba giờ.',NULL,0),(16,16,'我们有四本书。','Wǒmen yǒu sì běn shū.','Chúng tôi có bốn quyển sách.',NULL,0),(17,17,'他有五个苹果。','Tā yǒu wǔ ge píngguǒ.','Anh ấy có năm quả táo.',NULL,0),(18,18,'今天是六号。','Jīntiān shì liù hào.','Hôm nay là ngày mùng sáu.',NULL,0),(19,19,'我七点去学校。','Wǒ qī diǎn qù xuéxiào.','Bảy giờ tôi đi đến trường.',NULL,0),(20,20,'他今年八岁。','Tā jīnnián bā suì.','Năm nay cậu ấy tám tuổi.',NULL,0),(21,21,'现在九点了。','Xiànzài jiǔ diǎn le.','Bây giờ chín giờ rồi.',NULL,0),(22,22,'这里有十个人。','Zhèlǐ yǒu shí ge rén.','Ở đây có mười người.',NULL,0),(23,23,'现在几点？','Xiànzài jǐ diǎn?','Bây giờ mấy giờ rồi?',NULL,0),(24,24,'这个多少钱？','Zhège duōshao qián?','Cái này bao nhiêu tiền?',NULL,0),(25,25,'我有三个朋友。','Wǒ yǒu sān ge péngyou.','Tôi có ba người bạn.',NULL,0),(26,26,'这本书二十块。','Zhè běn shū èrshí kuài.','Quyển sách này hai mươi tệ.',NULL,0),(27,27,'我买了一本书。','Wǒ mǎile yì běn shū.','Tôi đã mua một quyển sách.',NULL,0),(28,28,'我买了一些水果。','Wǒ mǎile yìxiē shuǐguǒ.','Tôi đã mua một ít hoa quả.',NULL,0),(29,29,'我女儿五岁。','Wǒ nǚ\'ér wǔ suì.','Con gái tôi năm tuổi.',NULL,0),(30,30,'今天天气很好。','Jīntiān tiānqì hěn hǎo.','Hôm nay thời tiết rất đẹp.',NULL,0),(31,31,'你好！我是李老师。','Nǐ hǎo! Wǒ shì Lǐ lǎoshī.','Xin chào! Tôi là cô giáo Lý.',NULL,0),(32,32,'谢谢你！','Xièxie nǐ!','Cảm ơn bạn!',NULL,0),(33,33,'不客气，再见！','Bú kèqi, zàijiàn!','Không có gì, tạm biệt nhé!',NULL,0),(34,34,'老师，再见！','Lǎoshī, zàijiàn!','Thưa cô, em chào cô ạ! (tạm biệt)',NULL,0),(35,35,'对不起，我不能去。','Duìbuqǐ, wǒ bù néng qù.','Xin lỗi, tôi không thể đi được.',NULL,0),(36,36,'没关系，我们明天去。','Méi guānxi, wǒmen míngtiān qù.','Không sao, ngày mai chúng ta đi.',NULL,0),(37,37,'请坐，喝杯茶。','Qǐng zuò, hē bēi chá.','Mời ngồi, uống chén trà ạ.',NULL,0),(38,38,'喂，你是谁？','Wèi, nǐ shì shéi?','A lô, ai đấy ạ?',NULL,0),(39,39,'我叫王小明。','Wǒ jiào Wáng Xiǎomíng.','Tôi tên là Vương Tiểu Minh.',NULL,0),(40,40,'他的名字是李明。','Tā de míngzi shì Lǐ Míng.','Tên của anh ấy là Lý Minh.',NULL,0),(41,41,'认识你很高兴。','Rènshi nǐ hěn gāoxìng.','Rất vui được quen biết bạn.',NULL,0),(42,42,'今天我很高兴。','Jīntiān wǒ hěn gāoxìng.','Hôm nay tôi rất vui.',NULL,0),(43,43,'王先生是我的老师。','Wáng xiānsheng shì wǒ de lǎoshī.','Ông Vương là thầy giáo của tôi.',NULL,0),(44,44,'李小姐在饭馆工作。','Lǐ xiǎojiě zài fànguǎn gōngzuò.','Cô Lý làm việc ở nhà hàng.',NULL,0),(45,45,'他是我的好朋友。','Tā shì wǒ de hǎo péngyou.','Anh ấy là bạn tốt của tôi.',NULL,0),(46,46,'我的同学都是中国人。','Wǒ de tóngxué dōu shì Zhōngguó rén.','Các bạn học của tôi đều là người Trung Quốc.',NULL,0),(47,47,'我们的老师很好。','Wǒmen de lǎoshī hěn hǎo.','Thầy giáo của chúng tôi rất tốt.',NULL,0),(48,48,'我是学生，他是老师。','Wǒ shì xuésheng, tā shì lǎoshī.','Tôi là học sinh, còn anh ấy là giáo viên.',NULL,0),(49,49,'我爸爸是医生。','Wǒ bàba shì yīshēng.','Bố tôi là bác sĩ.',NULL,0),(50,50,'我妈妈在家。','Wǒ māma zài jiā.','Mẹ tôi đang ở nhà.',NULL,0),(51,51,'我的儿子六岁了。','Wǒ de érzi liù suì le.','Con trai tôi sáu tuổi rồi.',NULL,0),(52,52,'他的女儿是学生。','Tā de nǚ\'ér shì xuésheng.','Con gái của anh ấy là học sinh.',NULL,0),(53,53,'我家有五个人。','Wǒ jiā yǒu wǔ ge rén.','Nhà tôi có năm người.',NULL,0),(54,54,'我爱我的家。','Wǒ ài wǒ de jiā.','Tôi yêu gia đình của tôi.',NULL,0),(55,55,'今天是星期一。','Jīntiān shì xīngqīyī.','Hôm nay là thứ Hai.',NULL,0),(56,56,'明天我去北京。','Míngtiān wǒ qù Běijīng.','Ngày mai tôi đi Bắc Kinh.',NULL,0),(57,57,'昨天我在家。','Zuótiān wǒ zài jiā.','Hôm qua tôi ở nhà.',NULL,0),(58,58,'我学汉语一年了。','Wǒ xué Hànyǔ yì nián le.','Tôi học tiếng Trung được một năm rồi.',NULL,0),(59,59,'现在是九月。','Xiànzài shì jiǔ yuè.','Bây giờ là tháng Chín.',NULL,0),(60,60,'今天是三月八号。','Jīntiān shì sān yuè bā hào.','Hôm nay là ngày 8 tháng 3.',NULL,0),(61,61,'今天星期几？','Jīntiān xīngqī jǐ?','Hôm nay là thứ mấy?',NULL,0),(62,62,'现在几点了？','Xiànzài jǐ diǎn le?','Bây giờ mấy giờ rồi?',NULL,0),(63,63,'你什么时候来？','Nǐ shénme shíhou lái?','Khi nào thì bạn đến?',NULL,0),(64,64,'现在是八点。','Xiànzài shì bā diǎn.','Bây giờ là tám giờ.',NULL,0),(65,65,'我看了十分钟电视。','Wǒ kànle shí fēnzhōng diànshì.','Tôi đã xem ti vi mười phút.',NULL,0),(66,66,'上午我去学校。','Shàngwǔ wǒ qù xuéxiào.','Buổi sáng tôi đi đến trường.',NULL,0),(67,67,'中午我在家吃饭。','Zhōngwǔ wǒ zài jiā chī fàn.','Buổi trưa tôi ăn cơm ở nhà.',NULL,0),(68,68,'下午我们去商店。','Xiàwǔ wǒmen qù shāngdiàn.','Buổi chiều chúng tôi đi cửa hàng.',NULL,0),(69,69,'我是中国人。','Wǒ shì Zhōngguó rén.','Tôi là người Trung Quốc.',NULL,0),(70,70,'我有很多朋友。','Wǒ yǒu hěn duō péngyou.','Tôi có rất nhiều bạn.',NULL,0),(71,71,'我的书在桌子上。','Wǒ de shū zài zhuōzi shàng.','Sách của tôi ở trên bàn.',NULL,0),(72,72,'我去学校。','Wǒ qù xuéxiào.','Tôi đi đến trường.',NULL,0),(73,73,'他明天来我家。','Tā míngtiān lái wǒ jiā.','Ngày mai anh ấy đến nhà tôi.',NULL,0),(74,74,'我五点回家。','Wǒ wǔ diǎn huí jiā.','Năm giờ tôi về nhà.',NULL,0),(75,75,'我住在北京。','Wǒ zhù zài Běijīng.','Tôi sống ở Bắc Kinh.',NULL,0),(76,76,'我喜欢吃中国菜。','Wǒ xǐhuan chī Zhōngguó cài.','Tôi thích ăn món ăn Trung Quốc.',NULL,0),(77,77,'我想喝一杯茶。','Wǒ xiǎng hē yì bēi chá.','Tôi muốn uống một tách trà.',NULL,0),(78,78,'你看，那是我的学校。','Nǐ kàn, nà shì wǒ de xuéxiào.','Bạn nhìn xem, đó là trường của tôi.',NULL,0),(79,79,'我喜欢听老师读汉语。','Wǒ xǐhuan tīng lǎoshī dú Hànyǔ.','Tôi thích nghe cô giáo đọc tiếng Trung.',NULL,0),(80,80,'我在读一本书。','Wǒ zài dú yì běn shū.','Tôi đang đọc một quyển sách.',NULL,0),(81,81,'他在写字。','Tā zài xiě zì.','Anh ấy đang viết chữ.',NULL,0),(82,82,'今天人很多。','Jīntiān rén hěn duō.','Hôm nay rất đông người.',NULL,0),(83,83,'商店里的人很少。','Shāngdiàn lǐ de rén hěn shǎo.','Trong cửa hàng rất ít người.',NULL,0),(84,84,'妈妈想吃苹果。','Māma xiǎng chī píngguǒ.','Mẹ muốn ăn táo.',NULL,0),(85,85,'我会说一点儿汉语。','Wǒ huì shuō yìdiǎnr Hànyǔ.','Tôi biết nói một chút tiếng Trung.',NULL,0),(86,86,'这个字怎么读？','Zhège zì zěnme dú?','Chữ này đọc thế nào?',NULL,0),(87,87,'今天天气怎么样？','Jīntiān tiānqì zěnmeyàng?','Thời tiết hôm nay thế nào?',NULL,0),(88,88,'你是学生吗？','Nǐ shì xuésheng ma?','Bạn là học sinh phải không?',NULL,0),(89,89,'我很好，你呢？','Wǒ hěn hǎo, nǐ ne?','Tôi khỏe, còn bạn thì sao?',NULL,0),(90,90,'这是老师的书。','Zhè shì lǎoshī de shū.','Đây là sách của cô giáo.',NULL,0),(91,91,'我吃了三个苹果。','Wǒ chī le sān gè píngguǒ.','Tôi đã ăn ba quả táo.',NULL,0),(92,92,'我和朋友去商店。','Wǒ hé péngyou qù shāngdiàn.','Tôi và bạn đi đến cửa hàng.',NULL,0),(93,93,'我们都是学生。','Wǒmen dōu shì xuésheng.','Chúng tôi đều là học sinh.',NULL,0),(94,94,'今天很热。','Jīntiān hěn rè.','Hôm nay rất nóng.',NULL,0),(95,95,'今天太冷了。','Jīntiān tài lěng le.','Hôm nay lạnh quá.',NULL,0),(96,96,'我不喜欢喝茶。','Wǒ bù xǐhuan hē chá.','Tôi không thích uống trà.',NULL,0),(97,97,'他们的学校很大。','Tāmen de xuéxiào hěn dà.','Trường học của họ rất lớn.',NULL,0),(98,98,'我的猫很小。','Wǒ de māo hěn xiǎo.','Con mèo của tôi rất nhỏ.',NULL,0),(99,99,'下雨的时候很冷。','Xià yǔ de shíhou hěn lěng.','Lúc trời mưa thì rất lạnh.',NULL,0),(100,100,'我想喝一点儿热茶。','Wǒ xiǎng hē yìdiǎnr rè chá.','Tôi muốn uống một chút trà nóng.',NULL,0),(101,101,'我会说汉语。','Wǒ huì shuō Hànyǔ.','Tôi biết nói tiếng Trung.',NULL,0),(102,102,'她的衣服很漂亮。','Tā de yīfu hěn piàoliang.','Quần áo của cô ấy rất đẹp.',NULL,0),(103,103,'书在桌子上。','Shū zài zhuōzi shàng.','Quyển sách ở trên bàn.',NULL,0),(104,104,'猫在椅子下。','Māo zài yǐzi xià.','Con mèo ở dưới ghế.',NULL,0),(105,105,'医院里人很多。','Yīyuàn lǐ rén hěn duō.','Trong bệnh viện có rất nhiều người.',NULL,0),(106,106,'学校前面有一个商店。','Xuéxiào qiánmiàn yǒu yí gè shāngdiàn.','Phía trước trường học có một cửa hàng.',NULL,0),(107,107,'我家后面有一个医院。','Wǒ jiā hòumiàn yǒu yí gè yīyuàn.','Phía sau nhà tôi có một bệnh viện.',NULL,0),(108,108,'明天你能来吗？','Míngtiān nǐ néng lái ma?','Ngày mai bạn có thể đến không?',NULL,0),(109,109,'今天的天气很好。','Jīntiān de tiānqì hěn hǎo.','Thời tiết hôm nay rất đẹp.',NULL,0),(110,110,'明天会下雨吗？','Míngtiān huì xià yǔ ma?','Ngày mai trời sẽ mưa không?',NULL,0),(111,111,'我想喝水。','Wǒ xiǎng hē shuǐ.','Tôi muốn uống nước.',NULL,0),(112,112,'妈妈买了很多菜。','Māma mǎi le hěn duō cài.','Mẹ đã mua rất nhiều thức ăn.',NULL,0),(113,113,'我喜欢喝茶。','Wǒ xǐhuan hē chá.','Tôi thích uống trà.',NULL,0),(114,114,'我中午吃了一些米饭。','Wǒ zhōngwǔ chī le yìxiē mǐfàn.','Buổi trưa tôi đã ăn một ít cơm.',NULL,0),(115,115,'商店里有很多水果。','Shāngdiàn lǐ yǒu hěn duō shuǐguǒ.','Trong cửa hàng có rất nhiều trái cây.',NULL,0),(116,116,'这些苹果很大。','Zhèxiē píngguǒ hěn dà.','Những quả táo này rất to.',NULL,0),(117,117,'桌子上有三个杯子。','Zhuōzi shàng yǒu sān gè bēizi.','Trên bàn có ba cái cốc.',NULL,0),(118,118,'我们在饭店吃饭。','Wǒmen zài fàndiàn chī fàn.','Chúng tôi ăn cơm ở nhà hàng.',NULL,0),(119,119,'我想买一些水果。','Wǒ xiǎng mǎi yìxiē shuǐguǒ.','Tôi muốn mua một ít trái cây.',NULL,0),(120,120,'这些衣服多少钱？','Zhèxiē yīfu duōshao qián?','Những bộ quần áo này bao nhiêu tiền?',NULL,0),(121,121,'商店里的东西很多。','Shāngdiàn lǐ de dōngxi hěn duō.','Đồ trong cửa hàng rất nhiều.',NULL,0),(122,122,'我去商店买东西。','Wǒ qù shāngdiàn mǎi dōngxi.','Tôi đi cửa hàng mua đồ.',NULL,0),(123,123,'我坐出租车去学校。','Wǒ zuò chūzūchē qù xuéxiào.','Tôi đi taxi đến trường.',NULL,0),(124,124,'他明天坐飞机回家。','Tā míngtiān zuò fēijī huí jiā.','Ngày mai anh ấy đi máy bay về nhà.',NULL,0),(125,125,'老师会开车。','Lǎoshī huì kāi chē.','Thầy giáo biết lái xe.',NULL,0),(126,126,'他坐在椅子上。','Tā zuò zài yǐzi shàng.','Anh ấy ngồi trên ghế.',NULL,0),(127,127,'医生在医院工作。','Yīshēng zài yīyuàn gōngzuò.','Bác sĩ làm việc ở bệnh viện.',NULL,0),(128,128,'妈妈在商店工作。','Māma zài shāngdiàn gōngzuò.','Mẹ làm việc ở cửa hàng.',NULL,0),(129,129,'爸爸在做饭。','Bàba zài zuò fàn.','Bố đang nấu cơm.',NULL,0),(130,130,'我在打电话。','Wǒ zài dǎ diànhuà.','Tôi đang gọi điện thoại.',NULL,0),(131,131,'我十点睡觉。','Wǒ shí diǎn shuìjiào.','Tôi đi ngủ lúc mười giờ.',NULL,0),(132,132,'我看见你的猫了。','Wǒ kànjiàn nǐ de māo le.','Tôi nhìn thấy con mèo của bạn rồi.',NULL,0),(133,133,'我没有钱。','Wǒ méiyǒu qián.','Tôi không có tiền.',NULL,0),(134,134,'他是中国人。','Tā shì Zhōngguó rén.','Anh ấy là người Trung Quốc.',NULL,0),(135,135,'他的妈妈是医生。','Tā de māma shì yīshēng.','Mẹ của anh ấy là bác sĩ.',NULL,0),(136,136,'我们的学校很漂亮。','Wǒmen de xuéxiào hěn piàoliang.','Trường của chúng tôi rất đẹp.',NULL,0),(137,137,'我喜欢看书。','Wǒ xǐhuan kàn shū.','Tôi thích đọc sách.',NULL,0),(138,138,'这个字我不认识。','Zhège zì wǒ bú rènshi.','Chữ này tôi không biết.',NULL,0),(139,139,'他的汉语很好。','Tā de Hànyǔ hěn hǎo.','Tiếng Trung của anh ấy rất tốt.',NULL,0),(140,140,'我在学校学习汉语。','Wǒ zài xuéxiào xuéxí Hànyǔ.','Tôi học tiếng Trung ở trường.',NULL,0),(141,141,'我很喜欢这本书。','Wǒ hěn xǐhuan zhè běn shū.','Tôi rất thích quyển sách này.',NULL,0),(142,142,'桌子上有一本书。','Zhuōzi shàng yǒu yì běn shū.','Trên bàn có một quyển sách.',NULL,0),(143,143,'这个椅子很漂亮。','Zhège yǐzi hěn piàoliang.','Cái ghế này rất đẹp.',NULL,0),(144,144,'妈妈买了很多衣服。','Māma mǎi le hěn duō yīfu.','Mẹ đã mua rất nhiều quần áo.',NULL,0),(145,145,'我在电脑上写字。','Wǒ zài diànnǎo shàng xiě zì.','Tôi viết chữ trên máy tính.',NULL,0),(146,146,'爸爸在家看电视。','Bàba zài jiā kàn diànshì.','Bố xem tivi ở nhà.',NULL,0),(147,147,'我和朋友去看电影。','Wǒ hé péngyou qù kàn diànyǐng.','Tôi và bạn đi xem phim.',NULL,0),(148,148,'我很喜欢猫。','Wǒ hěn xǐhuan māo.','Tôi rất thích mèo.',NULL,0),(149,149,'他的狗很大。','Tā de gǒu hěn dà.','Con chó của anh ấy rất to.',NULL,0),(150,150,'我明天去北京。','Wǒ míngtiān qù Běijīng.','Ngày mai tôi đi Bắc Kinh.',NULL,0),(151,151,'我们一起去吃饭吧！','Wǒmen yìqǐ qù chīfàn ba!','Chúng ta cùng đi ăn cơm nhé!',NULL,0),(152,152,'她今天穿了一件白色的衣服。','Tā jīntiān chuān le yí jiàn báisè de yīfu.','Hôm nay cô ấy mặc một chiếc áo màu trắng.',NULL,0),(153,153,'这本书一百二十块钱。','Zhè běn shū yìbǎi èrshí kuài qián.','Quyển sách này giá một trăm hai mươi tệ.',NULL,0),(154,154,'谢谢你帮助我学习汉语。','Xièxie nǐ bāngzhù wǒ xuéxí Hànyǔ.','Cảm ơn bạn đã giúp tôi học tiếng Hán.',NULL,0),(155,155,'爸爸每天早上都看报纸。','Bàba měitiān zǎoshang dōu kàn bàozhǐ.','Sáng nào bố tôi cũng đọc báo.',NULL,0),(156,156,'今天比昨天冷一点儿。','Jīntiān bǐ zuótiān lěng yìdiǎnr.','Hôm nay lạnh hơn hôm qua một chút.',NULL,0),(157,157,'别在教室里说话。','Bié zài jiàoshì lǐ shuōhuà.','Đừng nói chuyện trong lớp học.',NULL,0),(158,158,'我们住在火车站旁边的宾馆。','Wǒmen zhù zài huǒchēzhàn pángbiān de bīnguǎn.','Chúng tôi ở khách sạn bên cạnh ga tàu hỏa.',NULL,0),(159,159,'这条路很长，走路要一个小时。','Zhè tiáo lù hěn cháng, zǒulù yào yí ge xiǎoshí.','Con đường này rất dài, đi bộ phải mất một tiếng.',NULL,0),(160,160,'妹妹唱歌唱得非常好。','Mèimei chànggē chàng de fēicháng hǎo.','Em gái tôi hát rất hay.',NULL,0),(161,161,'他刚出门，你等一下吧。','Tā gāng chū mén, nǐ děng yíxià ba.','Anh ấy vừa ra ngoài, bạn đợi một chút nhé.',NULL,0),(162,162,'天气冷了，你要多穿衣服。','Tiānqì lěng le, nǐ yào duō chuān yīfu.','Trời lạnh rồi, bạn phải mặc thêm áo.',NULL,0),(163,163,'我去过三次中国。','Wǒ qù guo sān cì Zhōngguó.','Tôi đã đến Trung Quốc ba lần.',NULL,0),(164,164,'他从公司到家要坐半个小时的车。','Tā cóng gōngsī dào jiā yào zuò bàn ge xiǎoshí de chē.','Từ công ty về đến nhà anh ấy phải đi xe nửa tiếng.',NULL,0),(165,165,'这个字你写错了。','Zhège zì nǐ xiě cuò le.','Chữ này bạn viết sai rồi.',NULL,0),(166,166,'弟弟每天下午都跟同学打篮球。','Dìdi měitiān xiàwǔ dōu gēn tóngxué dǎ lánqiú.','Chiều nào em trai tôi cũng chơi bóng rổ với bạn học.',NULL,0),(167,167,'大家好，我来介绍一下我的朋友。','Dàjiā hǎo, wǒ lái jièshào yíxià wǒ de péngyou.','Chào mọi người, tôi xin giới thiệu một chút về bạn của tôi.',NULL,0),(168,168,'火车九点到北京。','Huǒchē jiǔ diǎn dào Běijīng.','Tàu hỏa đến Bắc Kinh lúc chín giờ.',NULL,0),(169,169,'他汉语说得很好。','Tā Hànyǔ shuō de hěn hǎo.','Anh ấy nói tiếng Hán rất giỏi.',NULL,0),(170,170,'请在门口等我五分钟。','Qǐng zài ménkǒu děng wǒ wǔ fēnzhōng.','Xin hãy đợi tôi năm phút ở cửa.',NULL,0),(171,171,'我弟弟今年十二岁，在上小学。','Wǒ dìdi jīnnián shí\'èr suì, zài shàng xiǎoxué.','Em trai tôi năm nay mười hai tuổi, đang học tiểu học.',NULL,0),(172,172,'这是我第一次坐飞机。','Zhè shì wǒ dì-yī cì zuò fēijī.','Đây là lần đầu tiên tôi đi máy bay.',NULL,0),(173,173,'老师说的话我都听懂了。','Lǎoshī shuō de huà wǒ dōu tīng dǒng le.','Những lời thầy giáo nói tôi đều nghe hiểu.',NULL,0),(174,174,'你说得对，我们明天早上去吧。','Nǐ shuō de duì, wǒmen míngtiān zǎoshang qù ba.','Bạn nói đúng, sáng mai chúng ta đi nhé.',NULL,0),(175,175,'这个房间很大，也很便宜。','Zhège fángjiān hěn dà, yě hěn piányi.','Căn phòng này rất rộng, mà cũng rất rẻ.',NULL,0),(176,176,'我非常喜欢学习汉语。','Wǒ fēicháng xǐhuan xuéxí Hànyǔ.','Tôi vô cùng thích học tiếng Hán.',NULL,0),(177,177,'服务员，请给我一杯咖啡。','Fúwùyuán, qǐng gěi wǒ yì bēi kāfēi.','Phục vụ ơi, cho tôi một ly cà phê.',NULL,0),(178,178,'我哥哥比我高一点儿。','Wǒ gēge bǐ wǒ gāo yìdiǎnr.','Anh trai tôi cao hơn tôi một chút.',NULL,0),(179,179,'请告诉我你什么时候到。','Qǐng gàosu wǒ nǐ shénme shíhou dào.','Xin cho tôi biết khi nào bạn đến.',NULL,0),(180,180,'我哥哥在一家公司工作。','Wǒ gēge zài yì jiā gōngsī gōngzuò.','Anh trai tôi làm việc ở một công ty.',NULL,0),(181,181,'妈妈给我买了一个新手机。','Māma gěi wǒ mǎi le yí ge xīn shǒujī.','Mẹ mua cho tôi một chiếc điện thoại mới.',NULL,0),(182,182,'我每天坐公共汽车去上班。','Wǒ měitiān zuò gōnggòng qìchē qù shàngbān.','Hằng ngày tôi đi xe buýt đi làm.',NULL,0),(183,183,'他们公司离火车站很近。','Tāmen gōngsī lí huǒchēzhàn hěn jìn.','Công ty của họ rất gần ga tàu hỏa.',NULL,0),(184,184,'这件衣服太贵了，有便宜一点儿的吗？','Zhè jiàn yīfu tài guì le, yǒu piányi yìdiǎnr de ma?','Chiếc áo này đắt quá, có cái nào rẻ hơn một chút không?',NULL,0),(185,185,'我没去过中国，但是很想去。','Wǒ méi qù guo Zhōngguó, dànshì hěn xiǎng qù.','Tôi chưa từng đến Trung Quốc, nhưng rất muốn đi.',NULL,0),(186,186,'他还在教室里做作业。','Tā hái zài jiàoshì lǐ zuò zuòyè.','Cậu ấy vẫn còn đang làm bài tập trong lớp học.',NULL,0),(187,187,'他们有两个孩子，一个男孩，一个女孩。','Tāmen yǒu liǎng ge háizi, yí ge nánhái, yí ge nǚhái.','Họ có hai đứa con, một trai và một gái.',NULL,0),(188,188,'妈妈做的鸡蛋面非常好吃。','Māma zuò de jīdàn miàn fēicháng hǎochī.','Mì trứng mẹ nấu rất ngon.',NULL,0),(189,189,'天黑了，我们快回家吧。','Tiān hēi le, wǒmen kuài huí jiā ba.','Trời tối rồi, chúng ta mau về nhà thôi.',NULL,0),(190,190,'她很喜欢那件红色的衣服。','Tā hěn xǐhuan nà jiàn hóngsè de yīfu.','Cô ấy rất thích chiếc áo màu đỏ kia.',NULL,0),(191,191,'请问，去火车站怎么走？','Qǐngwèn, qù huǒchēzhàn zěnme zǒu?','Xin hỏi, đi đến ga tàu hỏa đi thế nào?',NULL,0),(192,192,'从这儿到机场要一个小时。','Cóng zhèr dào jīchǎng yào yí ge xiǎoshí.','Từ đây đến sân bay mất một tiếng.',NULL,0),(193,193,'我每天早上吃两个鸡蛋，喝一杯牛奶。','Wǒ měitiān zǎoshang chī liǎng ge jīdàn, hē yì bēi niúnǎi.','Mỗi sáng tôi ăn hai quả trứng gà và uống một cốc sữa.',NULL,0),(194,194,'我想买两件新衣服。','Wǒ xiǎng mǎi liǎng jiàn xīn yīfu.','Tôi muốn mua hai chiếc áo mới.',NULL,0),(195,195,'我们的教室里有很多学生。','Wǒmen de jiàoshì lǐ yǒu hěn duō xuésheng.','Trong lớp học của chúng tôi có rất nhiều học sinh.',NULL,0),(196,196,'我姐姐是老师，她在中国工作。','Wǒ jiějie shì lǎoshī, tā zài Zhōngguó gōngzuò.','Chị gái tôi là giáo viên, chị ấy làm việc ở Trung Quốc.',NULL,0),(197,197,'我来给大家介绍一下我的新同学。','Wǒ lái gěi dàjiā jièshào yíxià wǒ de xīn tóngxué.','Tôi xin giới thiệu với mọi người bạn học mới của tôi.',NULL,0),(198,198,'请进，外面很冷。','Qǐng jìn, wàimiàn hěn lěng.','Mời vào, bên ngoài rất lạnh.',NULL,0),(199,199,'我家离学校很近，走路十分钟就到了。','Wǒ jiā lí xuéxiào hěn jìn, zǒulù shí fēnzhōng jiù dào le.','Nhà tôi rất gần trường, đi bộ mười phút là đến.',NULL,0),(200,200,'你在这儿等一下，我一会儿就来。','Nǐ zài zhèr děng yíxià, wǒ yíhuìr jiù lái.','Bạn đợi ở đây một lát, tôi đến ngay.',NULL,0),(201,201,'我觉得这个问题很有意思。','Wǒ juéde zhège wèntí hěn yǒu yìsi.','Tôi thấy vấn đề này rất thú vị.',NULL,0),(202,202,'早上我喜欢喝一杯热咖啡。','Zǎoshang wǒ xǐhuan hē yì bēi rè kāfēi.','Buổi sáng tôi thích uống một tách cà phê nóng.',NULL,0),(203,203,'我们的汉语课八点开始。','Wǒmen de Hànyǔ kè bā diǎn kāishǐ.','Lớp tiếng Hán của chúng tôi bắt đầu lúc tám giờ.',NULL,0),(204,204,'下个星期我们有一次汉语考试。','Xià ge xīngqī wǒmen yǒu yí cì Hànyǔ kǎoshì.','Tuần sau chúng tôi có một kỳ thi tiếng Hán.',NULL,0),(205,205,'今天下午我没有课，可以去运动。','Jīntiān xiàwǔ wǒ méiyǒu kè, kěyǐ qù yùndòng.','Chiều nay tôi không có tiết học, có thể đi vận động.',NULL,0),(206,206,'他今天可能不来上课。','Tā jīntiān kěnéng bù lái shàngkè.','Hôm nay có thể cậu ấy không đến lớp.',NULL,0),(207,207,'这儿的东西很便宜，你可以去看看。','Zhèr de dōngxi hěn piányi, nǐ kěyǐ qù kànkan.','Đồ ở đây rất rẻ, bạn có thể đi xem thử.',NULL,0),(208,208,'快一点儿，公共汽车来了！','Kuài yìdiǎnr, gōnggòng qìchē lái le!','Nhanh lên một chút, xe buýt đến rồi!',NULL,0),(209,209,'祝你生日快乐！','Zhù nǐ shēngrì kuàilè!','Chúc bạn sinh nhật vui vẻ!',NULL,0),(210,210,'今天工作了十个小时，我很累。','Jīntiān gōngzuò le shí ge xiǎoshí, wǒ hěn lèi.','Hôm nay làm việc mười tiếng, tôi rất mệt.',NULL,0),(211,211,'我们学校离机场不远。','Wǒmen xuéxiào lí jīchǎng bù yuǎn.','Trường chúng tôi cách sân bay không xa.',NULL,0),(212,212,'我有两个哥哥，一个姐姐。','Wǒ yǒu liǎng ge gēge, yí ge jiějie.','Tôi có hai anh trai và một chị gái.',NULL,0),(213,213,'现在是十点零五分。','Xiànzài shì shí diǎn líng wǔ fēn.','Bây giờ là mười giờ năm phút.',NULL,0),(214,214,'去宾馆的路我不认识，我们问问吧。','Qù bīnguǎn de lù wǒ bú rènshi, wǒmen wènwen ba.','Đường đến khách sạn tôi không biết, chúng ta hỏi thử nhé.',NULL,0),(215,215,'去年我去中国旅游了两个星期。','Qùnián wǒ qù Zhōngguó lǚyóu le liǎng ge xīngqī.','Năm ngoái tôi đi du lịch Trung Quốc hai tuần.',NULL,0),(216,216,'这儿卖的水果很好吃，也很便宜。','Zhèr mài de shuǐguǒ hěn hǎochī, yě hěn piányi.','Hoa quả bán ở đây rất ngon và cũng rất rẻ.',NULL,0),(217,217,'请你说慢一点儿，我听不懂。','Qǐng nǐ shuō màn yìdiǎnr, wǒ tīng bu dǒng.','Bạn hãy nói chậm một chút, tôi nghe không hiểu.',NULL,0),(218,218,'爸爸这几天工作很忙。','Bàba zhè jǐ tiān gōngzuò hěn máng.','Mấy hôm nay bố tôi làm việc rất bận.',NULL,0),(219,219,'我每天早上六点起床。','Wǒ měitiān zǎoshang liù diǎn qǐchuáng.','Mỗi ngày tôi thức dậy lúc sáu giờ sáng.',NULL,0),(220,220,'我妹妹今年上小学，她很喜欢唱歌。','Wǒ mèimei jīnnián shàng xiǎoxué, tā hěn xǐhuan chànggē.','Em gái tôi năm nay học tiểu học, em ấy rất thích hát.',NULL,0),(221,221,'教室的门开着，里面没有人。','Jiàoshì de mén kāi zhe, lǐmiàn méiyǒu rén.','Cửa lớp học đang mở, bên trong không có ai.',NULL,0),(222,222,'那个男孩子是我弟弟的同学。','Nàge nán háizi shì wǒ dìdi de tóngxué.','Cậu bé kia là bạn học của em trai tôi.',NULL,0),(223,223,'老师，您好！请问您有时间吗？','Lǎoshī, nín hǎo! Qǐngwèn nín yǒu shíjiān ma?','Thưa thầy, em chào thầy ạ! Xin hỏi thầy có thời gian không ạ?',NULL,0),(224,224,'弟弟每天早上都要喝一杯牛奶。','Dìdi měitiān zǎoshang dōu yào hē yì bēi niúnǎi.','Sáng nào em trai tôi cũng uống một cốc sữa.',NULL,0),(225,225,'她是我姐姐的女儿，今年五岁。','Tā shì wǒ jiějie de nǚ\'ér, jīnnián wǔ suì.','Cô bé là con gái của chị gái tôi, năm nay năm tuổi.',NULL,0),(226,226,'这是我的妻子，她是老师。','Zhè shì wǒ de qīzi, tā shì lǎoshī.','Đây là vợ tôi, cô ấy là giáo viên.',NULL,0),(227,227,'我每天六点起床。','Wǒ měi tiān liù diǎn qǐchuáng.','Mỗi ngày tôi dậy lúc sáu giờ.',NULL,0),(228,228,'这个手机三千块钱。','Zhège shǒujī sān qiān kuài qián.','Chiếc điện thoại này giá ba nghìn tệ.',NULL,0),(229,229,'我有两支铅笔和一本书。','Wǒ yǒu liǎng zhī qiānbǐ hé yì běn shū.','Tôi có hai cây bút chì và một quyển sách.',NULL,0),(230,230,'明天是晴天，我们去公园吧。','Míngtiān shì qíngtiān, wǒmen qù gōngyuán ba.','Ngày mai trời nắng, chúng ta đi công viên đi.',NULL,0),(231,231,'北京的秋天很漂亮。','Běijīng de qiūtiān hěn piàoliang.','Mùa thu ở Bắc Kinh rất đẹp.',NULL,0),(232,232,'去年我去了中国。','Qùnián wǒ qùle Zhōngguó.','Năm ngoái tôi đã đi Trung Quốc.',NULL,0),(233,233,'妈妈让我早点儿回家。','Māma ràng wǒ zǎodiǎnr huí jiā.','Mẹ bảo tôi về nhà sớm một chút.',NULL,0),(234,234,'今天是五月一日。','Jīntiān shì wǔ yuè yī rì.','Hôm nay là ngày mùng một tháng năm.',NULL,0),(235,235,'我爸爸每天八点上班。','Wǒ bàba měi tiān bā diǎn shàngbān.','Bố tôi ngày nào cũng đi làm lúc tám giờ.',NULL,0),(236,236,'他的身体很好，常常运动。','Tā de shēntǐ hěn hǎo, chángcháng yùndòng.','Sức khoẻ anh ấy rất tốt, anh ấy thường xuyên vận động.',NULL,0),(237,237,'他生病了，今天不能来上课。','Tā shēngbìng le, jīntiān bù néng lái shàngkè.','Anh ấy bị ốm rồi, hôm nay không thể đến lớp.',NULL,0),(238,238,'祝你生日快乐！','Zhù nǐ shēngrì kuàilè!','Chúc bạn sinh nhật vui vẻ!',NULL,0),(239,239,'你明天有时间吗？','Nǐ míngtiān yǒu shíjiān ma?','Ngày mai bạn có thời gian không?',NULL,0),(240,240,'我今天有很多事情要做。','Wǒ jīntiān yǒu hěn duō shìqing yào zuò.','Hôm nay tôi có rất nhiều việc phải làm.',NULL,0),(241,241,'这块手表太贵了。','Zhè kuài shǒubiǎo tài guì le.','Chiếc đồng hồ này đắt quá.',NULL,0),(242,242,'我的手机在桌子上。','Wǒ de shǒujī zài zhuōzi shang.','Điện thoại của tôi ở trên bàn.',NULL,0),(243,243,'请你慢点儿说话。','Qǐng nǐ màn diǎnr shuōhuà.','Xin bạn nói chậm một chút.',NULL,0),(244,244,'生日的时候，我送她一本书。','Shēngrì de shíhou, wǒ sòng tā yì běn shū.','Vào dịp sinh nhật, tôi tặng cô ấy một quyển sách.',NULL,0),(245,245,'虽然很累，但是我很高兴。','Suīrán hěn lèi, dànshì wǒ hěn gāoxìng.','Tuy rất mệt nhưng tôi rất vui.',NULL,0),(246,246,'因为下雨，所以我没去。','Yīnwèi xià yǔ, suǒyǐ wǒ méi qù.','Vì trời mưa nên tôi đã không đi.',NULL,0),(247,247,'这是我的猫，它很漂亮。','Zhè shì wǒ de māo, tā hěn piàoliang.','Đây là con mèo của tôi, nó rất đẹp.',NULL,0),(248,248,'我喜欢和朋友一起踢足球。','Wǒ xǐhuan hé péngyou yìqǐ tī zúqiú.','Tôi thích đá bóng cùng bạn bè.',NULL,0),(249,249,'这道题太难了，我不会做。','Zhè dào tí tài nán le, wǒ bú huì zuò.','Bài này khó quá, tôi không biết làm.',NULL,0),(250,250,'她跳舞跳得很好。','Tā tiàowǔ tiào de hěn hǎo.','Cô ấy nhảy rất đẹp.',NULL,0),(251,251,'门外有人在等你。','Mén wài yǒu rén zài děng nǐ.','Bên ngoài cửa có người đang đợi bạn.',NULL,0),(252,252,'我看完这本书了。','Wǒ kàn wán zhè běn shū le.','Tôi đã đọc xong quyển sách này rồi.',NULL,0),(253,253,'孩子们在外面玩。','Háizimen zài wàimiàn wán.','Bọn trẻ đang chơi ở bên ngoài.',NULL,0),(254,254,'今天晚上我们去看电影。','Jīntiān wǎnshang wǒmen qù kàn diànyǐng.','Tối nay chúng ta đi xem phim.',NULL,0),(255,255,'往前走，医院就在右边。','Wǎng qián zǒu, yīyuàn jiù zài yòubian.','Đi thẳng về phía trước, bệnh viện ở bên phải.',NULL,0),(256,256,'你为什么不来上课？','Nǐ wèi shénme bù lái shàngkè?','Tại sao bạn không đến lớp?',NULL,0),(257,257,'我想问你一个问题。','Wǒ xiǎng wèn nǐ yí ge wèntí.','Tôi muốn hỏi bạn một câu hỏi.',NULL,0),(258,258,'这个问题很难回答。','Zhège wèntí hěn nán huídá.','Câu hỏi này rất khó trả lời.',NULL,0),(259,259,'夏天我喜欢吃西瓜。','Xiàtiān wǒ xǐhuan chī xīguā.','Mùa hè tôi thích ăn dưa hấu.',NULL,0),(260,260,'我希望明天不下雨。','Wǒ xīwàng míngtiān bú xià yǔ.','Tôi hy vọng ngày mai trời không mưa.',NULL,0),(261,261,'吃饭以前要洗手。','Chī fàn yǐqián yào xǐ shǒu.','Trước khi ăn cơm phải rửa tay.',NULL,0),(262,262,'请问，洗手间在哪儿？','Qǐngwèn, xǐshǒujiān zài nǎr?','Xin hỏi, nhà vệ sinh ở đâu?',NULL,0),(263,263,'这里的夏天非常热。','Zhèlǐ de xiàtiān fēicháng rè.','Mùa hè ở đây rất nóng.',NULL,0),(264,264,'我每天学习两个小时。','Wǒ měi tiān xuéxí liǎng ge xiǎoshí.','Mỗi ngày tôi học hai tiếng.',NULL,0),(265,265,'听了他的话，大家都笑了。','Tīngle tā de huà, dàjiā dōu xiào le.','Nghe anh ấy nói, mọi người đều cười.',NULL,0),(266,266,'这是我的新手机。','Zhè shì wǒ de xīn shǒujī.','Đây là chiếc điện thoại mới của tôi.',NULL,0),(267,267,'您贵姓？我姓王。','Nín guìxìng? Wǒ xìng Wáng.','Ngài họ gì ạ? Tôi họ Vương.',NULL,0),(268,268,'你累了，休息一下吧。','Nǐ lèi le, xiūxi yíxià ba.','Bạn mệt rồi, nghỉ một lát đi.',NULL,0),(269,269,'昨天下了很大的雪。','Zuótiān xiàle hěn dà de xuě.','Hôm qua tuyết rơi rất to.',NULL,0),(270,270,'你喜欢什么颜色？','Nǐ xǐhuan shénme yánsè?','Bạn thích màu gì?',NULL,0),(271,271,'她的眼睛又大又漂亮。','Tā de yǎnjing yòu dà yòu piàoliang.','Đôi mắt cô ấy vừa to vừa đẹp.',NULL,0),(272,272,'这家饭馆的羊肉很好吃。','Zhè jiā fànguǎn de yángròu hěn hǎochī.','Thịt cừu của quán ăn này rất ngon.',NULL,0),(273,273,'医生让我每天吃三次药。','Yīshēng ràng wǒ měi tiān chī sān cì yào.','Bác sĩ bảo tôi mỗi ngày uống thuốc ba lần.',NULL,0),(274,274,'我要一杯咖啡，谢谢。','Wǒ yào yì bēi kāfēi, xièxie.','Tôi muốn một ly cà phê, cảm ơn.',NULL,0),(275,275,'他是学生，我也是学生。','Tā shì xuésheng, wǒ yě shì xuésheng.','Anh ấy là học sinh, tôi cũng là học sinh.',NULL,0),(276,276,'我们一起去吃饭吧。','Wǒmen yìqǐ qù chī fàn ba.','Chúng ta cùng đi ăn cơm đi.',NULL,0),(277,277,'他已经回家了。','Tā yǐjīng huí jiā le.','Anh ấy đã về nhà rồi.',NULL,0),(278,278,'这个词是什么意思？','Zhège cí shì shénme yìsi?','Từ này có nghĩa là gì?',NULL,0),(279,279,'今天是阴天，可能会下雨。','Jīntiān shì yīntiān, kěnéng huì xià yǔ.','Hôm nay trời âm u, có thể sẽ mưa.',NULL,0),(280,280,'因为身体不舒服，所以他没来上班。','Yīnwèi shēntǐ bù shūfu, suǒyǐ tā méi lái shàngbān.','Vì trong người không khoẻ nên anh ấy đã không đi làm.',NULL,0),(281,281,'我用手机看新闻。','Wǒ yòng shǒujī kàn xīnwén.','Tôi dùng điện thoại để xem tin tức.',NULL,0),(282,282,'夏天我常常去游泳。','Xiàtiān wǒ chángcháng qù yóuyǒng.','Mùa hè tôi thường đi bơi.',NULL,0),(283,283,'医院在超市的右边。','Yīyuàn zài chāoshì de yòubian.','Bệnh viện nằm ở bên phải siêu thị.',NULL,0),(284,284,'妈妈做的鱼很好吃。','Māma zuò de yú hěn hǎochī.','Cá mẹ nấu rất ngon.',NULL,0),(285,285,'我家离学校不远。','Wǒ jiā lí xuéxiào bù yuǎn.','Nhà tôi cách trường không xa.',NULL,0),(286,286,'每天运动对身体很好。','Měi tiān yùndòng duì shēntǐ hěn hǎo.','Tập thể dục mỗi ngày rất tốt cho sức khoẻ.',NULL,0),(287,287,'请你再说一遍。','Qǐng nǐ zài shuō yí biàn.','Xin bạn nói lại một lần nữa.',NULL,0),(288,288,'我早上七点起床。','Wǒ zǎoshang qī diǎn qǐchuáng.','Buổi sáng tôi dậy lúc bảy giờ.',NULL,0),(289,289,'桌子上有一张纸。','Zhuōzi shang yǒu yì zhāng zhǐ.','Trên bàn có một tờ giấy.',NULL,0),(290,290,'她的丈夫是医生。','Tā de zhàngfu shì yīshēng.','Chồng cô ấy là bác sĩ.',NULL,0),(291,291,'我在找我的手机。','Wǒ zài zhǎo wǒ de shǒujī.','Tôi đang tìm điện thoại của tôi.',NULL,0),(292,292,'他坐着看书。','Tā zuòzhe kàn shū.','Anh ấy ngồi đọc sách.',NULL,0),(293,293,'今天真冷，你多穿点儿吧。','Jīntiān zhēn lěng, nǐ duō chuān diǎnr ba.','Hôm nay lạnh thật đấy, bạn mặc thêm đồ vào đi.',NULL,0),(294,294,'我正在做饭，一会儿给你打电话。','Wǒ zhèngzài zuò fàn, yíhuìr gěi nǐ dǎ diànhuà.','Tôi đang nấu cơm, lát nữa gọi điện cho bạn.',NULL,0),(295,295,'我不知道他在哪儿。','Wǒ bù zhīdào tā zài nǎr.','Tôi không biết anh ấy ở đâu.',NULL,0),(296,296,'我学中文两年了。','Wǒ xué Zhōngwén liǎng nián le.','Tôi học tiếng Trung được hai năm rồi.',NULL,0),(297,297,'我在准备明天的考试。','Wǒ zài zhǔnbèi míngtiān de kǎoshì.','Tôi đang chuẩn bị cho kỳ thi ngày mai.',NULL,0),(298,298,'我们走着去吧，不太远。','Wǒmen zǒuzhe qù ba, bú tài yuǎn.','Chúng ta đi bộ đi, không xa lắm đâu.',NULL,0),(299,299,'这是我最喜欢的电影。','Zhè shì wǒ zuì xǐhuan de diànyǐng.','Đây là bộ phim tôi thích nhất.',NULL,0),(300,300,'银行在学校的左边。','Yínháng zài xuéxiào de zuǒbian.','Ngân hàng nằm ở bên trái trường học.',NULL,0);
